(window.TNQ=window.TNQ||[]).push({"terms":{"동질지역":{"d":"지리적으로 인구나 산업 같은 성격이 비슷한 지역으로 묶은 지역 구분입니다.","r":["결절지역"]},"결절지역":{"d":"중심지와 주변이 기능적으로 서로 연결되어 하나의 통일체를 이루는 지역입니다.","r":["동질지역"]},"성장거점이론":{"d":"성장 가능성이 큰 거점에 투자를 집중해 주변으로 효과가 퍼지게 하는 개발 이론입니다.","r":[]},"환지계획":{"d":"환지처분을 위해 환지설계와 필지별 환지·청산 명세를 정하는 계획입니다.","r":[]},"체비지":{"d":"사업비를 마련하려고 환지로 돌려주지 않고 남겨 두는 토지입니다.","r":["환지계획"]},"중심지이론":{"d":"도시와 거점들이 시장 범위에 따라 계층을 이루며 배치된다고 설명하는 이론입니다.","r":[]},"근린주구":{"d":"초등학교 한 곳이 필요한 규모의 인구가 모여 사는 주거 생활의 기본 단위입니다.","r":[]},"쿨데삭":{"d":"끝이 막힌 막다른 도로로 통과교통을 막아 안전한 주거지를 만드는 도로형입니다.","r":[]},"입지계수":{"d":"지역의 산업 비중을 전국 비중과 견주어 그 산업의 특화 정도를 나타내는 값입니다.","r":[]},"변이할당분석":{"d":"지역 산업의 변화를 국가성장, 산업구조, 지역경쟁력 효과로 나누어 보는 분석입니다.","r":[]},"지구단위계획":{"d":"특정 지구의 토지이용과 건축을 구체적으로 정하는 도시관리계획입니다.","r":[]},"어반 스프롤":{"d":"도시가 계획 없이 교외로 무질서하게 퍼져 나가는 현상입니다.","r":[]},"테크노폴리스":{"d":"산업, 학술, 주거 기능이 어우러진 첨단 기술 중심의 도시입니다.","r":[]},"집단생잔법":{"d":"기준년도 인구에 출생, 사망, 이동을 반영해 장래 인구를 추정하는 방법입니다.","r":[]},"등비급수법":{"d":"해마다 일정한 비율로 인구가 늘어난다고 보고 장래 인구를 추정하는 방법입니다.","r":[]},"토지구획정리사업":{"d":"대지의 효용을 높이고 공공시설을 정비하려고 토지를 재배분하는 사업입니다.","r":[]},"입찰지대":{"d":"토지 이용자가 각 위치에서 낼 용의가 있는 최대 지대로, 중심에서 멀수록 낮아집니다.","r":[]},"공동구":{"d":"전기, 통신, 상하수도 같은 여러 시설을 한곳에 묶어 수용하는 지하 구조물입니다.","r":[]},"옹호적 계획":{"d":"계획가가 약자나 소외된 집단의 이익을 대변해 계획안을 만드는 방식입니다.","r":[]},"집적경제":{"d":"기업과 인구가 한곳에 모일 때 생기는 비용 절감 같은 경제적 이익입니다.","r":[]},"압축도시":{"d":"토지를 복합적으로 쓰고 고밀로 개발해 이동과 에너지를 줄이는 도시 형태입니다.","r":[]},"시가화조정구역":{"d":"도시의 무질서한 시가화를 막으려고 일정 기간 시가화를 유보하는 용도구역입니다.","r":[]},"개발제한구역":{"d":"도시의 무질서한 확산을 막고 자연환경을 보전하려고 개발을 제한하는 용도구역입니다.","r":[]},"인동간격":{"d":"앞뒤로 마주 보는 건물 사이의 거리로 일조와 프라이버시를 고려해 정합니다.","r":[]},"관리처분계획":{"d":"정비사업에서 분양설계와 보류지 등을 정해 권리를 배분하는 계획입니다.","r":[]},"유클리드 지역제":{"d":"용도를 미리 확정해 필지 단위로 규제하는 전통적 지역제입니다.","r":[]},"삼각망":{"d":"측량할 지역을 삼각형으로 연결해 각 점의 위치를 구하는 그물 모양 구성입니다.","r":[]},"등고선":{"d":"지형에서 같은 높이의 점을 이어 놓은 선입니다.","r":[]},"시장실패":{"d":"시장에 맡겨 두었을 때 자원이 효율적으로 배분되지 않는 현상입니다.","r":[]},"종주도시":{"d":"한 나라의 인구와 기능이 가장 큰 도시 하나에 지나치게 쏠린 도시입니다.","r":[]},"지수성장모형":{"d":"인구가 정해진 비율로 늘어난다고 보고 장래 인구를 구하는 모형입니다.","r":[]},"델파이법":{"d":"전문가 집단에게 설문을 반복하며 의견을 수렴하는 정성적 예측 기법입니다.","r":[]},"기반시설":{"d":"도로, 공원, 상하수도처럼 도시 기능을 유지하는 데 필요한 시설입니다.","r":[]},"용도지구":{"d":"용도지역의 기능을 보완하려고 경관, 미관, 보호 등을 위해 따로 지정하는 지구입니다.","r":[]},"용도구역":{"d":"토지이용을 제한하거나 유도하기 위해 지정하는 구역으로 개발제한구역 등이 있습니다.","r":[]},"전원도시":{"d":"하워드가 제안한 도시와 농촌의 장점을 결합한 자급자족형 소규모 도시입니다.","r":[]},"래드번":{"d":"슈퍼블록과 보차분리를 적용한 미국의 계획 주거단지입니다.","r":[]},"슈퍼블록":{"d":"여러 가구를 합쳐 만든 큰 가구로, 내부에 통과교통을 막고 보차분리를 합니다.","r":[]},"수출기반모형":{"d":"지역경제를 수출 부문과 지역 내 소비 부문으로 나누어 성장을 설명하는 모형입니다.","r":[]},"버제스":{"d":"시카고를 연구해 동심원이론을 제시한 도시생태학자입니다.","r":[]},"점이지대":{"d":"동심원이론에서 도심과 주거지대 사이에 있는 전환 지대입니다.","r":[]},"차경":{"d":"멀리 있는 자연이나 경치를 빌려 풍경의 일부로 삼는 기법입니다.","r":[]},"듀플렉스":{"d":"한 주호가 두 개 층을 쓰는 메조넷 주택의 형태입니다.","r":[]}},"notes":{"1/500 도면의 면적은 실제 면적의 1/1,000이 아니라 1/250,000이다":"도면 면적은 실제 면적의 1/1,000이 아니라 1/250,000 비율로 줄어든 값입니다.","1/600 도면을 1/200으로 확대하면 크기는 3배가 아니라 9배가 된다":"1/600 도면을 1/200으로 확대하면 길이는 3배, 면적은 9배가 됩니다.","100만㎡ 이상 주택지·아파트지구 조성사업, 30만㎡ 이상 공장용지 조성사업":"주택지·아파트지구는 100만㎡ 이상, 공장용지는 30만㎡ 이상 조성할 때 대규모개발사업으로 봅니다.","100만㎡ 이상 택지·주택사업, 30만㎡ 이상 공업용지조성사업이 대상이다":"인구영향평가를 받아야 하는 규모는 택지·주택사업 100만㎡, 공업용지조성 30만㎡ 이상입니다.","100세대 이상이면 300㎡(시·군은 200㎡)에 세대 초과분을 더해 산정한다":"어린이놀이터는 100세대 이상이면 300㎡(시·군은 200㎡)에 세대 초과분을 더해 면적을 구합니다.","10년이 아니라 20년 단위의 장기계획이다":"광역도시계획은 10년이 아니라 20년을 내다보는 장기계획이에요.","10년 전보다 커졌다면 수위도시로 인구가 더 집중되었다는 뜻이다":"q가 10년 전보다 커졌다면 가장 큰 도시로 인구가 더 몰렸다는 의미입니다.","10만㎡ 이상의 택지조성사업은 자연보전권역에서 허용되지 않는다":"택지조성사업이 10만㎡ 이상이면 자연보전권역에서는 할 수 없어요.","18홀 이상 골프장은 108만㎡를 초과할 수 없다":"18홀 이상 골프장의 면적은 108만㎡를 넘길 수 없습니다.","18홀 이상일 때 숙박시설을 설치할 수 있으며 9홀 이상은 아니다":"골프장은 18홀 이상일 때 숙박시설을 둘 수 있고 9홀 이상으로는 안 됩니다.","1902년 아디케스법은 시당국이 민간 토지를 계획에 맞춰 재배분하는 최초의 토지구획정리법이다":"1902년의 아디케스법은 시가 민간 토지를 계획에 맞게 다시 나눠 준 첫 토지구획정리 법률이에요.","1920년대 위성도시안은 테일러·라딩·휘튼이 제안했고 기버드는 그 이후다":"1920년대 위성도시안은 테일러, 라딩, 휘튼이 냈고 기버드는 그 뒤 인물입니다.","1958년 헤이그 세미나는 재개발을 전면재개발·수복재개발·보전재개발로 분류했다":"1958년 헤이그 세미나는 재개발을 전면, 수복, 보전의 세 가지로 나눴습니다.","1962년 도시계획법 제정으로 일제 잔재를 청산했고 1981년 개정으로 20년 장기 도시기본계획을 제도화했다":"1962년 도시계획법으로 일제 잔재를 정리했고, 1981년 개정으로 20년을 내다보는 도시기본계획이 제도가 됐습니다.","1개 주호가 2개 층을 쓰면 듀플렉스라 하며 프라이버시가 좋고 엘리베이터 효율이 높아진다":"한 가구가 위아래 두 층을 쓰는 형태가 듀플렉스이고, 사생활이 좋고 엘리베이터를 효율적으로 쓸 수 있어요.","1단계 집행계획에 포함되지 않은 토지는 그 기간 동안 사업을 시행할 수 없다":"1단계 집행계획에서 빠진 땅에서는 그 단계가 진행되는 동안 도시계획시설사업을 못 합니다.","1만㎡ 이상이면 도시개발구역으로 지정할 수 있다":"도시지역 안에서는 1만㎡ 이상이면 도시개발구역으로 지정할 수 있어요.","1이 아니라 0보다 작을 때 사업성이 없다고 평가한다":"NPV는 1이 아니라 0보다 작으면 사업성이 없다고 평가합니다.","1차 자료보다 적은 비용으로 빠르게 얻을 수 있다":"남이 만들어 둔 것을 가져다 쓰므로 비용과 시간이 덜 듭니다.","20% 이하이며 체육공원은 이와 다른 비율을 적용받는다":"도시자연공원은 20% 이하이고 체육공원은 다른 비율이 적용됩니다.","2000년 도시계획법 개정으로 지구단위계획제도가 도입되었으며 상세계획제도는 도시계획법에 따른 것이었다":"2000년 도시계획법을 고쳐 지구단위계획제도를 들였고, 상세계획제도는 도시계획법에 따른 것이었어요.","2011~2020 수정계획은 방재능력 강화, 글로벌 거점기능 강화, 저탄소 녹색국토를 정책방향으로 삼았다":"수정계획은 방재, 글로벌 거점, 저탄소 녹색국토 세 가지를 2011~2020년의 정책방향으로 잡았어요.","20년이 아니라 10년 단위로 수립하며 5년마다 타당성을 재검토한다":"정비기본계획은 20년이 아니라 10년 단위로 세우고 5년마다 타당성을 재검토해요.","2·3차 산업 비중 증가와 인구 집중을 동반하며 주변지역 영향력을 키운다":"도시화가 진행되면 2·3차 산업 비중이 늘고 인구가 모이며 주변 지역에 미치는 영향력도 커집니다.","24시간 개방되며 최소폭·단차·포장 기준을 갖춘다":"공공보행통로는 하루 종일 열려 있어야 하며 최소 폭, 단차, 포장 기준을 갖춥니다.","2년 이내 하수발생량이 시설용량을 초과할 것으로 예상되는 지역도 지정 대상이다":"2년 안에 하수 발생량이 처리용량을 넘을 것으로 보이는 곳도 지정 대상에 듭니다.","2차적 경관요소는 규제·인센티브, 3차적 요소는 인간의지와 무관한 비물리적 영역이다":"2차적 경관요소는 규제와 인센티브이고, 3차적 요소는 사람의 의지와 관계없는 비물리적 영역입니다.","3,000㎡ 미만 공공시설의 위치·면적 변경은 승인이 필요한 사항이다":"3,000㎡ 미만 공공시설이라도 위치나 면적을 바꾸려면 승인을 받아야 해요.","3만㎡가 아니라 1만㎡ 이상이 기준이다":"상업지역도 3만㎡가 아니라 1만㎡ 이상이 기준입니다.","4단계 절차는 예비개발계획→최종개발계획→개별개발계획 등으로 진행된다":"PUD는 예비계획을 거쳐 최종계획, 개별계획으로 이어지는 단계 절차를 밟습니다.","500세대 기준에서 설치 의무 시설이 아니다":"유치원은 500세대 기준에서 꼭 짓도록 정해진 시설에 들지 않습니다.","5~15%보다 더 낮은 수준":"녹지지역의 도로율은 5~15%보다도 낮은 수준입니다.","5년 이상 20년 이내이며 20년으로 고정된 것은 아니다":"유보기간은 5년 이상 20년 이내이며 20년으로 못 박혀 있지는 않습니다.","5년이 아니라 10년마다 수립한다":"관광개발기본계획은 5년이 아니라 10년마다 세웁니다.","5만㎡ 이상이면 1세대당 2㎡ 이상 또는 부지면적의 5% 중 큰 면적을 확보한다":"5만㎡ 이상 사업에서는 세대당 2㎡ 이상과 부지면적 5% 중 넓은 쪽만큼 공원을 확보해야 합니다.","6만㎡ 이하 관광지조성·도시개발사업, 전문대학 소규모 이전이 심의를 거쳐 허용된다":"6만㎡ 이하의 관광지 조성이나 도시개발과 전문대학 소규모 이전은 심의를 받으면 허용됩니다.","70년대 이후에는 종속이론·소득분배이론·기본수요이론 같은 상향식 대안이 등장했다":"70년대 이후에는 종속이론, 소득분배이론, 기본수요이론처럼 아래에서 위로 가는 대안이 나왔습니다.","B/C비는 1 이상이어야 타당성이 있다고 보며, NPV는 편익의 현재가치에서 비용의 현재가치를 뺀 값이다":"B/C비가 1 이상이어야 타당하고, 순현재가치는 편익의 현재가치에서 비용의 현재가치를 뺀 값입니다.","BLT는 준공 후 일정 기간 정부에 운영권을 주고, BOO는 준공과 동시에 민간이 소유권을 갖는다":"BLT는 완공 뒤 일정 기간 정부에 운영권을 빌려주는 방식이고, BOO는 완공되면 곧바로 민간이 소유합니다.","BLT는 준공 후 정부에 운영권을 임대하며, BOO는 사업자가 소유권을 갖는 방식이다":"정부에 운영권을 임대하는 쪽이 BLT이고, 사업자가 소유권을 가지는 쪽이 BOO입니다.","CBD, 중공업지역, 교외주거지역":"다핵심이론의 기능지역에는 CBD, 중공업지역, 교외주거지역이 있어요.","Green GNP, 압축도시, 복합토지이용":"친환경 도시를 위한 방법으로 Green GNP, 압축도시, 복합토지이용이 있어요.","IRR이 자본비용보다 크거나 PI가 1보다 크면 사업성이 있다고 본다":"내부수익률이 자본비용을 넘거나 수익성지수가 1을 넘으면 투자할 만하다고 판단합니다.","Pn=Po(1+r)ⁿ 공식으로 매년 일정 비율 증가를 가정한다":"등비급수법은 Pn=Po(1+r)ⁿ 공식을 써서 해마다 일정한 비율로 늘어난다고 가정해요.","Pn=Po·e^(rn) 공식이며 연도 경과에 따라 급격한 인구 증가를 보일 때 쓴다":"지수곡선법은 Pn=Po·e^(rn) 공식이며 해가 지날수록 인구가 급하게 늘어날 때 씁니다.","P는 주차수요, U는 첨두시 용도별 발생량, F는 계획 건물연면적이다":"주차발생원단위법에서 P는 주차수요, U는 첨두 시간대 용도별 발생량, F는 계획 건물의 연면적입니다.","P코드뿐 아니라 C/A코드도 변조한다":"신호에는 P코드뿐 아니라 C/A코드도 실려 있습니다.","REDWAY로 차량·보행을 분리하고 격자형 간선도로, 외향적 근린주구로 계획됐다":"밀톤케인즈는 REDWAY로 차량과 보행을 나누고 격자형 간선도로와 바깥을 향한 근린주구로 계획됐습니다.","Robert Goodland(1994)는 경제적·환경적·사회적 지속성을 제안했다":"Goodland는 1994년에 지속성을 경제, 환경, 사회의 세 갈래로 제안했습니다.","UN이 제시한 기본수요 구성 변수는 식량·의류·안전이며 토지는 아니다":"UN이 든 기본수요의 구성 변수는 식량, 의류, 안전이고 토지는 들어 있지 않습니다.","가구규모와 구성, 인구규모와 구성, 고용자수":"수요를 예측할 때 쓰는 정량적 변수는 가구 규모와 구성, 인구 규모와 구성, 고용자 수입니다.","가구를 구획하는 도로는 집산도로가 아니라 국지도로다":"가구를 나누는 길은 집산도로가 아니라 국지도로가 맡아요.","가구 크기를 소형화하는 것은 비용 절감 원칙이 아니다":"가구 크기를 작게 하는 것은 비용을 줄이는 원칙으로 보지 않습니다.","가장 정확하고 배각법은 방위각법보다 읽기오차가 작다":"각관측법 중 배각법이 가장 정확하고, 읽기오차는 방위각법보다 작습니다.","각 관측 정밀도가 거리 측량보다 좋을 때 위거·경거에 배분한다":"트랜싯법칙은 각 관측이 거리 측량보다 정밀할 때 위거와 경거에 맞춰 오차를 배분합니다.","각 권역은 과밀 정도와 개발 관리 방향에 따라 정해진다":"각 권역은 얼마나 붐비는지와 개발을 어떻게 관리할지에 따라 정해집니다.","각 기능 요소가 차량 중심 동선으로 직접 연결되어야 하는 것은 아니다":"각 기능을 차량 동선으로 직접 연결해야만 복합용도개발이 되는 것은 아닙니다.","각의 크기와 무관하게 등분하여 오차를 배분한다":"관측 정확도가 같으면 각의 크기와 상관없이 똑같이 나눠 오차를 배분해요.","각 주호에 균등한 환경조건을 주지만 외부공간이 획일적이고 단조로워지기 쉽다":"평행배치는 각 주호의 환경을 비슷하게 맞추지만 바깥 공간이 지루하고 같은 모양이 되기 쉽습니다.","간선도로변 가설건물·저층건물 난립 방지는 최고높이 규제가 아니라 최저높이 규제 사유다":"간선도로변에 가설건물이나 저층건물이 난립하는 것을 막는 것은 최고높이가 아니라 최저높이 규제의 이유입니다.","개량재개발·전환재개발은 이 국제 분류에 속하지 않는다":"개량재개발과 전환재개발은 이 국제 분류에 들어가지 않아요.","개발가치가 낮고 생산성이 떨어지며 개발기술이 부족한 자원이지 고갈된 자원은 아니다":"한계자원은 다 써서 없어진 자원이 아니라 개발 가치와 생산성이 낮고 기술이 모자라 쓰기 어려운 자원입니다.","개발과 환경의 조화를 바탕으로 균형 있는 발전과 경쟁력을 추구한다":"개발과 환경이 조화를 이루는 바탕 위에서 균형 있는 발전과 경쟁력을 추구해요.","개발신탁·관리신탁·국공유지신탁":"신탁회사의 주요 업무는 개발신탁, 관리신탁, 국공유지신탁입니다.","개발유도지역의 지가·규제가 강할수록 개발권 수요는 오히려 늘어난다":"개발유도지역의 지가가 오르고 규제가 강해질수록 개발권을 사려는 수요는 오히려 늘어납니다.","개발유형은 도심형·주거중심형·신시가지형이며 교외도시형은 없다":"서울 뉴타운은 도심형, 주거중심형, 신시가지형으로 나뉘고 교외도시형은 없어요.","개발이익은 공유화하고 토지도 공유화하는 것이 원칙이다":"개발로 생기는 이익을 모두의 몫으로 하고 토지도 공동으로 소유하는 것이 원칙입니다.","개발이익 환수(주제를 서로 바꿔 알면 틀린다)":"어스와트 보고서는 개발이익 환수를 다룹니다.","개발제한구역·시가화조정구역·수산자원보호구역이 있다":"용도구역에는 개발제한구역, 시가화조정구역, 수산자원보호구역이 있어요.","개발제한구역 지정은 수도권정비계획의 규제수단이 아니라 별도 제도다":"개발제한구역을 지정하는 일은 수도권정비계획 수단이 아니라 다른 제도입니다.","개발제한구역 훼손을 억제하고 관리 재원을 확보하기 위해 징수한다":"개발제한구역이 훼손되는 것을 억제하고 관리에 쓸 재원을 마련하려고 징수해요.","개발제한에 대한 보상으로 공정성을 확보하고 시장기구를 활용해 자원배분 왜곡을 줄인다":"개발을 제한한 것에 보상을 해 주니 공정하고, 시장 기구를 활용해 자원배분이 왜곡되는 것을 줄입니다.","개발주체가 토지를 매입·수용하지 않는 것이 환지방식 토지구획정리사업의 특징이다":"환지방식은 개발하는 주체가 토지를 사들이거나 수용하지 않는다는 점이 특징입니다.","개발진흥지구, 특정용도제한지구, 시설보호지구는 용도지구이며 자연환경보전지구는 용도지역이다":"용도지구에는 개발진흥, 특정용도제한, 시설보호가 있고 자연환경보전지구는 용도지역에 속해요.","개발진흥지구는 이 완화 대상에 포함되지 않는다":"용적률을 완화해 주는 대상에 개발진흥지구는 끼지 않습니다.","거리, 제품 단위가격, 생산단위비용으로 결정되며 인구밀도와는 무관하다":"토지의 지대는 거리, 제품 단위가격, 생산단위비용으로 정해지며 인구밀도와는 관계가 없습니다.","거리·각 정밀도가 같을 때 측선 길이에 비례해 배분한다":"컴파스법칙은 거리와 각 정밀도가 같을 때 측선 길이에 비례해 오차를 나눠 줍니다.","거리의 제곱에 비례하거나 크기에 반비례하지 않는다":"거리의 제곱에 비례하거나 크기에 반비례한다는 설명은 반대로 쓴 것입니다.","건물 높이 4m 이하는 1m 이상, 8m 이하는 2m 이상 인접대지경계선에서 띄운다":"전용주거지역에서는 건물 높이 4m 이하이면 1m 이상, 8m 이하이면 2m 이상 인접대지경계선에서 띄웁니다.","건물 높이의 약 2배 거리에서 봐야 건축을 전체로 볼 수 있다고 했다":"건물 높이의 두 배쯤 떨어져야 건물 전체가 한눈에 들어온다고 헷지맨과 피이츠는 봤어요.","건물 사용목적에 맞게 구성하고 일사(햇빛)를 방해하지 않도록 한다":"획지와 가구는 건물을 쓰는 목적에 맞게 짜고 햇빛을 가로막지 않도록 합니다.","건물 종류에 따라 폭·깊이를 정하고 원형 가구는 피한다":"건물 종류에 맞게 폭과 깊이를 정하고, 동그란 모양의 가구는 피합니다.","건설비를 줄이려면 급경사·암반 노출을 피하고 상하수도 인접지를 택하되 구배 0%는 피한다":"급경사와 암반을 피하고 상하수도가 가까운 땅을 골라야 하며, 구배가 0%인 평지는 배수 때문에 피합니다.","건축물 건축, 형질변경, 1개월 이상 물건 적재는 원칙적으로 개발행위허가가 필요하다":"건축물을 짓거나 형질을 바꾸거나 한 달 넘게 물건을 쌓아 두려면 원칙적으로 개발행위허가를 받아야 해요.","건축물 높이 한도, 배치·형태·색채, 경관계획은 도시계획위원회·건축위원회 공동심의 대상이다":"높이 한도와 배치·형태·색채, 경관계획은 두 위원회가 함께 심의하는 사항입니다.","건축물부설광장은 이용효과를 높이기 위해, 지하광장은 교통처리와 휴식 제공을 위해 설치한다":"건축물부설광장은 건물 이용의 효과를 높이려고, 지하광장은 교통을 처리하고 쉴 곳을 주려고 둡니다.","건축물 소유권 자체를 제한하는 것은 토지이용 규제 수단이 아니다":"건물의 소유권을 제한하는 것은 토지이용을 규제하는 방법에 들지 않습니다.","건축물의 배치·형태·색채·건축선, 경관계획은 도시기본계획이 아니라 하위 계획 사항이다":"건물 배치와 형태와 색채, 건축선과 경관계획은 도시기본계획이 아닌 그 아래 계획에서 다룹니다.","건축물의 허용·불허용 용도는 공동심의 대상이 아니다":"건축물의 허용 용도와 불허 용도는 두 위원회의 공동심의 대상이 아닙니다.","건축비의 100분의 10을 부과 원칙으로 한다":"과밀부담금은 건축비의 100분의 10을 부과하는 것이 원칙입니다.","건축·용도변경, 형질변경·분할, 도시계획사업은 개발제한구역에서 원칙적으로 허용되지 않는다":"개발제한구역에서는 건축과 용도변경, 형질변경과 분할, 도시계획사업을 원칙적으로 허용하지 않아요.","건폐율 90% 이하, 용적률 1,500% 이하 기준을 적용받는다":"주차전용건축물은 건폐율 90% 이하, 용적률 1,500% 이하 기준을 적용받아요.","건폐율은 대지면적 대비 건축면적 비율, 용적률은 대지면적 대비 연면적 비율이다":"대지에서 건물이 차지하는 바닥 비율이 건폐율이고, 건물 전체 바닥면적 비율이 용적률입니다.","건폐율이 일정하다고 용적률도 일정한 것은 아니다":"건폐율이 같아도 층수가 달라지면 용적률은 달라질 수 있어요.","게데스가 제시한 도시활동 구분 요소가 아니다":"교통은 게데스가 제시한 도시활동 구분 요소에 들지 않습니다.","견고한 지반에 설치하고 상호 시준이 잘 되며 정삼각형에 가깝게 선정한다":"삼각점은 단단한 지반에 세우고 서로 잘 보이게 하며 모양은 정삼각형에 가깝게 잡습니다.","결정조서·결정도·계획설명서이며 환경성검토서는 포함되지 않는다":"작성하는 도서는 결정조서, 결정도, 계획설명서이며 환경성검토서는 들어가지 않습니다.","경관 개선, 환경친화적 교통체계, 쾌적한 도시공간 확보":"경관을 개선하고 환경친화적 교통체계를 만들며 쾌적한 도시공간을 확보하는 것이 기본 목표입니다.","경관광장·교통광장·지하광장·건축물부설광장 등으로 나뉜다":"광장은 경관광장, 교통광장, 지하광장, 건축물부설광장 등으로 나뉩니다.","경관광장은 휴식·오락·경관보전, 근린광장은 사교·오락·휴식, 역전광장은 교통혼잡 방지가 목적이다":"경관광장은 쉼과 경관보전, 근린광장은 사교와 쉼, 역전광장은 혼잡 방지를 위해 둡니다.","경로당(노인정), 어린이놀이터, 운동장을 설치해야 한다":"경로당, 어린이놀이터, 운동장은 이 규모의 단지가 반드시 설치해야 하는 시설입니다.","경사 4% 이하는 평탄하고, 10% 이상도 자연경사대로 건축 가능하며, 25% 이상은 잔디깎기 기계를 못 쓴다":"경사 4% 이하는 평탄하고 10% 이상에서도 자연경사대로 건축하지만, 25% 이상이면 잔디깎기 기계를 쓰기 어렵습니다.","경사지에서는 건물 길이 방향을 등고선에 따르게 하고 긴 건물은 단차를 둔다":"경사지에서는 건물의 긴 방향을 등고선과 나란히 하고 긴 건물에는 높낮이 차이를 둡니다.","계층구조와 지역 내 기능적·상호의존적 관계로 형성된다":"결절지역은 중심과 주변이 계층적으로 이어지며 기능상 서로 의존할 때 생깁니다.","계층확산은 도시계층 구성에, 전염확산은 거리의 마찰효과에 더 큰 영향을 받는다":"계층확산은 도시의 위계에, 전염확산은 거리가 일으키는 마찰에 더 크게 좌우됩니다.","계획관리지역·개발진흥지구를 체계적으로 개발·관리하기 위한 것이다":"둘째 유형은 계획관리지역과 개발진흥지구를 체계적으로 개발하고 관리하려는 계획입니다.","계획안에 무관심한 사람들의 이익까지 대변하려 한다":"계획안에 관심이 없는 사람들의 이익까지 대변하려는 범위를 가집니다.","계획의 영향을 받는 사람들과의 상호 교류·대화로 계획을 수립한다":"계획에 영향을 받는 사람들과 서로 이야기하며 계획을 세우는 방식입니다.","계획인구를 3~5만 명 정도로 제한하고 주변에 농업지대를 두어 자급자족한다":"하워드는 계획인구를 3~5만 명으로 제한하고 주변에 농업지대를 두어 자급자족하게 했어요.","고도지구·특정용도제한지구는 이 기준으로 경관상세계획을 수립하는 원칙 대상이 아니다":"고도지구와 특정용도제한지구는 경관상세계획을 세워야 하는 원칙적 대상에서 빠집니다.","고밀화와 공동 오픈스페이스 확보에 유리하지만 프라이버시·개성 있는 외관 확보는 불리하다":"비접지형은 밀도를 높이고 함께 쓰는 열린 공간을 확보하기 좋지만, 사생활과 외관의 개성은 얻기 어렵습니다.","고속 교통기관을 도입하며 저밀도 전원도시를 추구하지 않는다":"고속 교통수단을 들이는 도시여서 낮은 밀도의 전원도시와는 방향이 다릅니다.","곡면을 평면으로 바꾸는 지도 투영은 필연적으로 왜곡을 일으키며 단일 투영으로 모든 왜곡을 없앨 수 없다":"둥근 땅을 평평한 지도로 옮기면 왜곡이 불가피하고, 한 가지 투영으로는 모든 왜곡을 없앨 수 없어요.","공간구조·기능분담, 녹지관리체계·환경보전, 광역시설 배치":"광역도시계획에는 공간구조와 기능분담, 녹지관리체계와 환경보전, 광역시설 배치가 들어갑니다.","공간구조·인구배분은 기본계획 내용이다":"공간구조와 인구배분은 도시관리계획이 아니라 기본계획의 내용입니다.","공공공간을 근린생활의 중심지로 조성하고 보행친화적 가로망을 만든다":"공공공간을 이웃 생활의 중심으로 삼고 걷기 편한 길망을 만듭니다.","공공·민간 활동의 분배효과를 고려하는 사회적 기능을 하며 개인행동을 우선시하지 않는다":"도시계획은 공공과 민간이 하는 일의 분배 효과를 살피며, 개인 행동을 앞세우지 않습니다.","공공시설부지를 제공하면 도시환경정비·재개발·재건축 정비구역, 상업지역에서 용적률을 200%까지 완화받을 수 있다":"공공시설부지를 내놓으면 정비구역과 상업지역에서 용적률을 200%까지 완화받을 수 있습니다.","공공의 이익요인, 경제적 요인, 사회적 요인":"샤핀이 든 토지이용 결정요인은 공공의 이익요인, 경제적 요인, 사회적 요인입니다.","공공의 이익을 일방적으로 규정하던 전통을 깨는 데 성공적이었다":"공공의 이익을 한쪽에서 규정하던 전통을 깨뜨렸다는 점에서 성공적이었어요.","공공재, 외부성, 위험과 불확실성은 시장실패를 일으키는 요인이다":"공공재와 외부성, 위험과 불확실성 때문에 시장이 제 구실을 못 하는 시장실패가 생깁니다.","공급측면을 강조하며 생산능력이 생산요소에 의존한다고 본다":"신고전 이론은 공급 측면을 강조해 생산능력이 생산요소에 달려 있다고 봅니다.","공동개발 준수, 대지 내 공지·통로 설치, 자연지반 보존":"공동개발을 지키거나 대지 안에 공지와 통로를 두거나 자연지반을 보존하면 인센티브를 받아요.","공동구, 공원, 광장, 도로, 상하수도, 공용주차장":"정비기반시설에는 공동구, 공원, 광장, 도로, 상하수도, 공용주차장이 있어요.","공동구 관리비용을 관할 시장·군수가 전액 부담하는 것은 아니며 수용 시설 사업자 등이 분담한다":"관리비용을 관할 시장과 군수가 전부 내는 것이 아니라 공동구에 설비를 넣는 사업자 등이 나눠 냅니다.","공동주택을 건설하는 주택단지에는 폭 6m 이상의 도로를 설치해야 한다":"공동주택을 짓는 단지 안에는 폭이 6m 이상인 도로를 둬야 해요.","공동주택을 건설하는 지점의 소음도 기준은 65dB 미만이다":"공동주택을 지을 수 있는 지점의 소음도는 65dB 미만이어야 합니다.","공동주택의 신축·증축·대수선·리모델링, 파손·철거 행위는 허가·신고 대상이다":"공동주택을 신축, 증축, 대수선, 리모델링하거나 파손, 철거할 때는 허가나 신고를 해야 합니다.","공동주택 일부가 붕괴 우려가 있거나 재해 위험이 있으면 재건축 정비계획을 수립할 수 있다":"공동주택 일부가 무너질 위험이 있거나 재해 위험이 있으면 재건축 정비계획을 세울 수 있습니다.","공동주택 일조 확보 기준은 하지가 아니라 동지를 기준으로 한다":"공동주택의 햇빛 확보 기준일은 하지가 아니라 동지입니다.","공무원이 아닌 위원의 임기는 2년이며 사무 처리를 위한 간사 1명을 둔다":"위원 중 공무원이 아닌 사람은 2년 임기이고 일을 처리할 간사 한 명이 따로 있어요.","공부(公簿)를 통해 토지·건물의 권리관계를 확인·보장하는 역할도 한다":"공부는 토지와 건물의 권리관계를 확인하고 지켜 주는 장부의 구실을 해요.","공업기술을 활용한 기능주의로 지역지구제·보차분리를 도입했다":"CIAM은 공업기술을 활용한 기능주의를 바탕으로 지역지구제와 보차분리를 도입했어요.","공업지역은 교통·용수·노동력이 편리하고 평탄하며 지가가 저렴한 곳이 적지이나 근린주구와는 분리돼야 한다":"교통, 용수, 노동력이 편리하고 평탄하며 지가가 싼 곳이 적지이되 근린주구와는 떨어져야 합니다.","공업지역은 토지적성평가를 생략할 수 있으나 주거지역은 환경성검토를 생략할 수 없다":"공업지역은 토지적성평가를 건너뛸 수 있지만 주거지역은 환경성검토를 건너뛸 수 없어요.","공영개발 방식의 확대는 집중 억제 대책이 아니라 오히려 집중을 유발할 수 있다":"공영개발 방식을 넓히는 것은 억제책이 되지 못하고 오히려 집중을 부를 수 있습니다.","공영·민간·제3섹터 개발방식으로 나뉜다":"신도시는 시행 주체에 따라 공영, 민간, 제3섹터 개발방식으로 나뉩니다.","공원, 하천, 공용주차장은 시장·군수가 비용을 부담할 수 있는 정비기반시설이다":"시장과 군수가 비용을 낼 수 있는 정비기반시설에는 공원과 하천, 공용주차장이 있습니다.","공원관리시설, 5개 이상 유희시설, 2종목 이상 운동·교양시설이 있다":"입장료를 받으려면 공원관리시설, 유희시설 5개 이상, 운동·교양시설 2종목 이상이 있어야 해요.","공원·운동장·초등학교·소규모 가게이며 점포를 중심에 집중시키지 않는다":"공원, 운동장, 초등학교, 작은 가게가 기본이며 점포를 한가운데에 몰아 두지 않습니다.","공장·대학의 신·증설 억제와 중앙행정 권한의 지방 이양":"공장과 대학의 신설·증설을 막고 중앙행정 권한을 지방으로 넘기는 것이 수도권 집중을 억제하는 대책입니다.","공장총량규제는 개별적 규제방식의 경직성을 완화하려고 도입되었다":"공장 총량규제는 하나씩 따지는 규제 방식이 경직되어 있어서 이를 누그러뜨리려고 도입했습니다.","공장 총량을 변경할 때도 수도권정비위원회 심의를 거쳐야 한다":"공장 총량을 바꿀 때도 수도권정비위원회 심의를 받아야 해요.","공장 총허용량의 지역별 배정은 국토교통부장관이 아니라 시·도지사가 정한다":"지역별로 공장 총허용량을 나누는 권한은 시·도지사에게 있고 국토교통부장관에게 있지 않아요.","공지율·밀도·용적률을 개발 허용·규제의 기초로 삼는다":"환경기준 가운데 공지율, 밀도, 용적률은 개발을 허용하거나 규제하는 기초로 씁니다.","과거 인구변화에 복리이율방식을 적용하는 것은 집단생잔법이 아니라 등비급수법이다":"과거의 인구 변화에 복리이자 계산을 붙이는 방식은 집단생잔법이 아니라 등비급수법입니다.","과밀부담금 부과, 총량규제, 대규모개발 영향평가는 수도권 과밀 해소 규제수단이다":"부담금, 총량규제, 영향평가는 수도권에 사람과 기능이 몰리는 것을 줄이는 수단이에요.","과밀억제권역·성장관리권역·자연보전권역":"수도권은 과밀억제권역, 성장관리권역, 자연보전권역으로 구분해요.","과밀지역은 클라센의 분류 항목이 아니다":"과밀지역이라는 구분은 클라센의 지역분류에 들어 있지 않습니다.","과잉도시화, 종주도시화, 지역적 불균형":"도시가 지나치게 커지고 한 도시에 쏠리며 지역 간 격차가 커지는 모습이 이 지역 도시화의 특징입니다.","과정지향적이며 환류(피드백)를 가지며 청사진식 계획이 아니다":"지역계획은 과정을 중시하고 환류를 가지며 미리 완성된 청사진을 그리는 계획이 아닙니다.","관계 중앙행정기관 공무원과 학식·경험이 풍부한 자 중에서 위촉한다":"중앙도시계획위원회 위원은 관계 중앙행정기관 공무원과 학식·경험이 풍부한 사람 중에서 위촉합니다.","관광권역의 설정은 권역별계획이 아니라 관광개발기본계획 사항이다":"관광권역을 정하는 일은 권역별 계획 단계가 아니라 그보다 위의 관광개발기본계획에서 합니다.","관광지개발·공업용지조성·택지개발사업은 대규모개발사업이나 도시재개발사업은 아니다":"관광지개발, 공업용지조성, 택지개발은 대규모개발사업이고, 도시재개발은 그 범위 밖입니다.","관리사무소, 운영 편의시설, 간이매점은 부대시설이나 자동차 수리·판매시설은 아니다":"주차장에 딸린 시설로는 관리사무소와 간이매점 등이 있으며, 차를 고치고 파는 시설은 해당하지 않아요.","관리지역은 보전·생산·계획관리지역별로 용적률 상한이 다르다":"관리지역 세 가지는 용적률 상한이 서로 다릅니다.","관찰법·면접법·설문지법은 현지조사이며 센서스 자료는 2차 자료다":"현지에 나가 관찰하고 면접하고 설문해서 얻는 것이 현지조사이고, 센서스처럼 이미 있는 자료는 2차 자료입니다.","광로 2류는 50m 이상 70m 미만이며 소로 2류는 10~12m가 아니다":"광로 2류는 50m 이상 70m 미만이고, 소로 2류의 폭은 문장과 다른 값입니다.","광역계획권의 장기 발전방향 제시는 도시관리계획이 아니라 광역도시계획이다":"광역계획권이 앞으로 어떻게 발전할지 길게 내다보는 일은 광역도시계획의 몫이에요.","광역성은 샤핀이 제시한 공공이익 요소가 아니다":"광역성은 샤핀이 말한 공공이익의 요소에 들어가지 않습니다.","광역시설 배치·규모, 공간구조·기능분담, 녹지관리·환경보전":"광역도시계획에는 광역시설의 배치와 규모, 공간구조와 기능분담, 녹지관리와 환경보전이 들어갑니다.","광역시설 설치에 드는 예산 자체에 관한 사항은 광역도시계획 내용에 포함되지 않는다":"광역시설을 설치하는 데 드는 예산 자체에 관한 사항은 광역도시계획의 내용이 아닙니다.","광장은 설치 목적과 위치에 따라 세분된다":"설치 목적과 위치에 따라 광장의 종류가 더 잘게 나뉩니다.","광장의 장변과 단변 비를 2:1로 보았다":"알베르티는 광장의 긴 변과 짧은 변의 비를 2:1로 보았습니다.","광파보다 기후 영향을 덜 받고 장거리용으로 쓰이며 최소 2인이 필요하다":"전파거리측량기는 날씨 영향을 덜 받아 먼 거리에 쓰이고 최소 두 사람이 필요해요.","교외가 아니라 도심의 재개발과 주거환경 개선이 특징이다":"재도시화 단계의 특징은 교외가 아니라 도심을 재개발하고 주거환경을 개선하는 것이에요.","교차로 주변에 다양한 규모로 계획하며 가구를 2열 이상 배열하지 않는다":"상업용지는 교차로 주변에 여러 규모로 계획하며 가구를 두 줄 이상 늘어놓지 않습니다.","교차점광장, 역전광장, 주요시설광장은 교통광장으로 분류된다":"교통광장에는 교차점광장, 역전광장, 주요시설광장이 있습니다.","교통·보건위생·방재시설이며 근린생활시설은 아니다":"도시계획시설은 교통, 보건위생, 방재 시설이며 근린생활시설은 해당하지 않습니다.","교통수요 발생은 다시 지가 상승 등 토지이용에 영향을 준다":"교통수요가 생기면 다시 땅값이 오르는 등 토지이용에 영향을 줍니다.","교통시설, 공간시설, 환경기초시설이나 아파트 등 주거시설은 아니다":"기반시설은 교통, 공간, 환경기초 시설을 가리키고 주거시설은 포함되지 않아요.","교통은 저장할 수 없는 유발수요이며 다른 활동을 보조하는 수단이지 그 자체가 목적은 아니다":"교통은 쌓아 놓을 수 없고 다른 활동을 위해 생기는 수요여서, 이동 자체가 목적은 아닙니다.","교통·통신 발달로 공간거리가 줄고 공공시설 투자가 중복되어 비효율이 생기면 광역행정화가 촉진된다":"교통과 통신 덕에 거리 부담이 줄고 공공시설 투자가 겹쳐 낭비가 생기면 광역행정으로 가는 흐름이 강해집니다.","구거, 사방설비, 행정청이 설치한 저수지는 공공시설이나 방음시설은 아니다":"구거와 사방설비와 행정청이 만든 저수지는 공공시설이고, 방음시설은 이 범위에 들지 않아요.","구체적인 개발계획 역할을 하며 개별 시민에게 구속력을 갖는다":"도시관리계획은 구체적인 개발계획 역할을 하며 시민 개개인에게 구속력을 갖습니다.","국가계획과 관련되면 국토교통부장관이, 같은 도 안이면 관할 시장·군수가 공동으로 수립한다":"국가계획과 얽히면 장관이, 한 도 안이면 시장·군수가 함께 광역도시계획을 세웁니다.","국가·지방자치단체, 지방공사, 일정 비율 이상 토지를 소유한 사업자는 택지개발사업 시행자가 될 수 있다":"국가, 지방자치단체, 지방공사, 일정 비율 이상 땅을 가진 사업자가 택지개발사업 시행자가 될 수 있어요.","국가·지방자치단체가 건축하는 건축물에는 부담금을 부과하지 않는다":"국가나 지방자치단체가 짓는 건축물에는 과밀부담금을 매기지 않아요.","국도 대체 우회도로·자동차전용도로에는 집산도로·국지도로를 직접 연결하지 않는다":"우회도로와 자동차전용도로에는 집산도로나 국지도로를 직접 잇지 않아요.","국제행사를 위한 대규모 공간 확보는 개발제한구역 지정 사유가 아니다":"국제행사를 위해 큰 공간을 확보하는 것은 개발제한구역을 지정하는 이유가 아닙니다.","국지도로는 모세혈관 역할로 가구 크기를 규격화하고 주거환경을 보호한다":"국지도로는 모세혈관처럼 가구 크기를 규격화하고 주거환경을 지키는 구실을 합니다.","국토계획법상 시설보호지구가 아니라 별도 법에 따른다":"군사시설보호지구는 국토계획법이 아니라 다른 법을 따릅니다.","국토 계획·정책 수립과 국토정보체계 구축을 위해 실시한다":"국토조사는 국토 계획과 정책을 세우고 국토정보체계를 구축하려고 하는 조사입니다.","국토계획·정책의 중요사항을 심의하기 위해 국무총리 소속으로 둔다":"국토계획과 정책의 중요한 사항을 심의하려고 국무총리 아래에 둡니다.","국토교통부장관·도지사·광역시장은 지정권자이나 구청장은 아니다":"지정권자에는 국토교통부장관과 도지사, 광역시장이 들고 구청장은 들지 않아요.","국토교통부장관이 실시하며 전문기관에 의뢰하거나 지자체에 자료를 요구할 수 있다":"국토교통부장관이 조사를 하고, 필요하면 전문기관에 맡기거나 지자체에 자료를 요구합니다.","국토교통부장관이 예정지구를 지정할 때는 미리 관계 중앙행정기관의 장과 협의해야 한다":"국토교통부장관은 예정지구를 지정하기 전에 관계 중앙행정기관의 장과 미리 협의합니다.","국토 및 지역계획은 배분적·성장유도적·쇄신적 계획으로 기능별 분류되며 지역적 계획이라는 구분은 없다":"국토 및 지역계획은 배분적, 성장유도적, 쇄신적 계획으로 나뉘고 지역적 계획이라는 구분은 없어요.","국토에 따른 사회체제(체계)의 개혁은 기본이념이 아니다":"국토에 따른 사회체제의 개혁은 기본이념에 들어가지 않아요.","국토의 계획 및 이용에 관한 법률은 여러 법률을 통합한 것이지 각각 다른 법률로 유지한 게 아니다":"국토의 계획 및 이용에 관한 법률은 따로 있던 여러 법이 하나로 합쳐진 결과예요.","국토의 공간구성과 관련된 모든 분야를 망라하는 종합계획이자 지침 제시적 계획이다":"국토의 공간구성에 관한 모든 분야를 망라하는 종합계획이자 방향을 제시하는 지침적 계획입니다.","국토종합계획, 도종합계획, 지역계획에 관한 사항을 심의하며 분과위원회를 둘 수 있다":"위원회는 국토종합계획, 도종합계획, 지역계획을 심의하고 필요하면 분과위원회를 둡니다.","국토종합계획과 부문별계획은 국토 전역을 대상으로 하며 시군종합계획은 국토계획법에 따른다":"국토종합계획과 부문별계획은 전국을 다루는 계획이고, 시군종합계획은 국토계획법의 틀을 따릅니다.","국토종합계획·지역계획·부문별계획이며 수도권정비계획은 별도 법에 따른다":"국토기본법상 계획은 종합, 지역, 부문별이며 수도권정비계획은 별도의 법에 따릅니다.","군락측도방법과 그린매트릭스 시스템은 경관분석기법이 아니다":"군락측도방법과 그린매트릭스 시스템은 경관분석기법으로 분류하지 않아요.","권리관계가 복잡한 기성 시가지에서는 시행하기 어렵다":"환지방식은 이해관계가 얽힌 기존 시가지에서는 추진하기 까다롭습니다.","권역을 동질지역·결절지역·계획지역으로 구분한다":"리차드슨은 권역을 성격에 따라 동질지역, 결절지역, 계획지역의 세 갈래로 나눴어요.","규모 3만㎡ 이상, 유치거리 1,000m 이하":"도보권 근린공원은 규모가 3만㎡ 이상이고 유치거리는 1,000m 이하입니다.","규범적 접근은 단편적·개괄적·점진적 방법으로 나뉘며 체계적 방법은 아니다":"해미드의 규범적 접근은 단편적, 개괄적, 점진적 방법으로 나뉘며 체계적 방법은 여기에 들지 않아요.","규제·실행수단을 제시하고 계획적 개발로 난개발을 억제한다":"규제하고 실행하는 수단을 내놓으며 계획적으로 개발해 난개발을 억제해요.","균형 있는 발전, 경쟁력 있는 국토여건 조성, 환경친화적 관리":"국토관리의 기본이념은 균형 있는 발전, 경쟁력 있는 국토여건 조성, 환경친화적 관리입니다.","그네·미끄럼틀·모래사장은 유희시설이며 야외음악당은 교양시설이다":"놀이기구인 그네와 미끄럼틀과 모래사장은 유희시설이고, 야외음악당은 교양시설입니다.","그리스보다 체계적으로 건설되었고 규모도 훨씬 컸다":"로마 도시는 그리스보다 체계적으로 건설됐고 규모도 훨씬 컸습니다.","근대 도시계획제도는 1934년 조선시가지계획령에서 비롯되었다":"근대적인 도시계획제도는 1934년 조선시가지계획령에서 시작됐어요.","근린생활권의 물적시설 계획에는 도로, 녹지공간, 학교가 포함된다":"근린생활권의 물적시설은 길, 초록 공간, 학교로 이루어집니다.","근린주구-소도시-메트로폴리스-코너베이션-메갈로폴리스 순으로 커진다":"거주 형태는 근린주구에서 소도시, 메트로폴리스, 코너베이션, 메갈로폴리스 순으로 커집니다.","기능 분화로 권역 내 자치단체 간 재정 불균형이 생기는 것도 이유다":"기능이 나뉘어 권역 안 자치단체끼리 재정 불균형이 생기는 것도 광역행정이 필요한 이유입니다.","기능에 따라 도로를 나누되 통과교통을 무조건 적극 방지하는 것이 원칙은 아니다":"기능별로 도로를 나누되 통과교통을 무조건 철저히 막는 것이 원칙은 아닙니다.","기능의 지나친 분리를 지양하고 혼합용도로 토지자원을 절약한다":"뉴어바니즘은 기능을 지나치게 나누지 않고 혼합용도로 토지자원을 아낍니다.","기명식 증권이며 발행규모가 분양 예정 토지가액 총액을 넘을 수는 없다":"기명식 증권으로 발행하며 총액은 분양할 토지가액의 합계를 넘길 수 없어요.","기반시설 광장은 일반광장·경관광장·건축물부설광장으로 구분되며 공중광장은 없다":"기반시설인 광장은 일반, 경관, 건축물부설의 세 가지이고 공중광장이란 구분은 없어요.","기반시설 구축, 자원·환경 관리, 토지 이용계획을 담는다":"도종합계획에는 기반시설을 갖추는 일, 자원과 환경 관리, 토지이용계획이 들어갑니다.","기반시설은 공공이 설치하고 주민은 환지방식으로 사업비를 부담한다":"자력재개발은 공공이 기반시설을 설치하고 주민은 환지방식으로 사업비를 부담합니다.","기반시설이 부족한 지역에 지정하며 학교·도로율 기준도 고려한다":"개발밀도관리구역은 기반시설이 모자란 곳에 지정하며 학교와 도로율 기준도 따집니다.","기버드가 설계했으며 고밀도가 아니라 저밀도 개발을 원칙으로 했다":"기버드가 설계한 할로우는 높은 밀도가 아니라 낮은 밀도를 지킨 도시입니다.","기본구상·대안설정단계는 목표에 따라 계획의 지침과 방향을 짜는 단계":"기본구상과 대안설정단계에서는 정한 목표에 따라 계획의 지침과 방향을 짭니다.","기본 성격·잠재력·생태적 특색을 파악하기 위한 것이다":"자연적 성질을 분석하는 것은 대지의 기본 성격과 잠재력, 생태적 특색을 알아내려는 것입니다.","기성 시가지나 대규모 신개발지구에서 토지이용을 합리화·구체화한다":"첫째 유형은 이미 만들어진 시가지나 큰 신개발지구에서 땅 쓰임을 알맞게 구체화하는 계획입니다.","기존 시가지의 정비·보전과 신시가지 개발 유형 구분이 해당한다":"기존 시가지를 정비하고 보전하는 유형과 새 시가지를 개발하는 유형으로 나뉩니다.","기준년도 인구에 출생률·사망률·인구이동을 반영해 장래인구를 추정한다":"기준년도 인구에 출생률, 사망률, 인구이동을 반영해 앞으로의 인구를 추정하는 방법입니다.","기지의 측점에 세운 표척의 읽음값이다":"후시는 높이를 아는 점에 세운 표척을 읽은 값입니다.","기회가 주어질 때마다 활용하는 유기적 계획으로 발달했다":"중세 도시는 기회가 올 때마다 하나씩 활용하는 유기적 계획으로 발달했습니다.","내부적 규모의 경제, 지방특화경제, 도시화경제로 구성된다":"집적경제는 내부적 규모의 경제, 지방특화경제, 도시화경제로 이루어집니다.","너비 3.3m 이상이며 경형구획 표시선 색상은 백색실선이 아니다":"장애인 전용구획은 너비를 3.3m 이상으로 하고, 경형구획 표시선은 백색실선이 아닙니다.","넓고 광대한 지역의 측량에 적합하다":"유심삼각망은 넓고 큰 지역을 측량하는 데 알맞아요.","노상·노외주차장을 가리키는 말이 아니라 기계식 장치를 설치한 주차장을 뜻한다":"기계식주차장은 노상이나 노외주차장을 가리키는 말이 아니라 기계 장치를 설치한 주차장을 말합니다.","노상주차장·노외주차장·부설주차장으로 나뉜다":"주차장은 노상, 노외, 부설주차장 세 종류로 나뉩니다.","노선배정 순이며 전통적으로 가장 많이 쓰인다":"교통수요 추정의 마지막 단계가 노선배정이며, 이 방법은 전통적으로 가장 널리 써 왔습니다.","노선 선정, 성토·절토 범위, 집수면적 산정에 쓰이나 지적도 작성에는 쓰이지 않는다":"등고선도는 노선을 정하고 성토·절토 범위와 집수면적을 구하는 데 쓰이지만 지적도 작성에는 쓰지 않습니다.","노외·노상주차장뿐 아니라 부설주차장도 포함하는 개념이다":"주차장은 노외주차장과 노상주차장뿐 아니라 부설주차장까지 아우르는 개념이에요.","녹지는 국토계획법상 도시기반시설에 포함된다":"녹지는 국토계획법에서 도시기반시설에 포함되는 시설이에요.","논리적 일관성으로 최적 대안을 찾거나 분석의 종합성을 강조하지 않는다":"논리적 일관성으로 최적 대안을 찾거나 분석을 종합적으로 하는 것을 강조하지 않아요.","농업과 공업을 결합한 이상 공장촌":"로버트 오웬은 농업과 공업을 결합한 이상 공장촌을 구상했어요.","농촌 청년의 대도시 유입과 성장지역으로의 자본 집적은 윌리암슨의 소득격차 요인이다":"농촌 청년이 대도시로 들어오고 자본이 성장지역에 쌓이는 것을 윌리암슨은 소득격차의 요인으로 꼽았습니다.","높다고 일조환경이 나빠지는 것은 아니다":"주택용지 비율이 높다고 곧바로 햇빛 환경이 나빠지는 것은 아닙니다.","높은 쇄신, 집적경제 효과, 양호한 교통시설은 공업의 중심지 집중을 촉진한다":"쇄신이 활발하고 집적경제 효과가 있으며 교통이 좋으면 공업이 중심지에 더 모여듭니다.","높이 8m를 초과하는 부분은 그 높이의 1/2 이상을 띄워야 한다":"높이가 8m를 넘는 부분은 그 높이의 2분의 1 이상을 띄워야 해요.","높이·깊이 50cm 이내의 형질변경, 녹지지역 25㎡ 이하 물건 적재도 허가 없이 가능하다":"높이나 깊이 50cm 이내의 형질변경과 녹지지역 25㎡ 이하 물건 적재는 허가가 필요 없습니다.","늘수록 접속 폭 기준도 커지지만 300~500세대에 10m, 500~1000세대에 14m는 아니다":"세대수가 많을수록 접속 폭을 넓히지만 문장에 적힌 10m와 14m는 알맞은 기준이 아닙니다.","다수 기업의 근접 입지, 생산·노동의 상호보완성, 편리한 인력 고용에서 비롯된다":"도시화경제는 많은 기업이 가까이 자리하고 생산과 노동이 서로 보완하며 인력을 쉽게 구하는 데서 나옵니다.","다수인의 집회·행사·사교를 위해 설치한다":"중심대광장은 많은 사람이 모여 집회하고 행사하고 사교하도록 설치해요.","다원주의·신보수주의를 바탕으로 도심회복과 혼합 용도지역을 추구한다":"포스트모던 도시론은 다원주의와 신보수주의를 바탕으로 도심회복과 혼합 용도지역을 추구합니다.","다중주택과 다가구주택은 공동주택이 아니라 단독주택으로 분류된다":"건축법은 다중주택과 다가구주택을 공동주택이 아닌 단독주택 쪽으로 분류해요.","단거리·대량수송이 필요하며 일정 시간대에 첨두현상이 나타난다":"도시교통은 짧은 거리에서 많은 사람을 날라야 하고 특정 시간대에 몰리는 첨두현상이 있습니다.","단계로 갈수록 주민이 실질적인 결정권을 갖는다":"주민권력 단계로 갈수록 주민이 결정권을 실질적으로 쥡니다.","단독·연립·중정형 주택처럼 땅에서 직접 접근하며 전용 뜰이 있다":"접지형은 단독, 연립, 중정형 주택처럼 땅에서 바로 들어가고 전용 뜰이 딸려 있어요.","단면 형태가 복잡해 구조·설비 설계에 세심한 고려가 필요하다":"단면 형태가 복잡하므로 구조와 설비를 설계할 때 세심하게 챙겨야 합니다.","단지 내 도로로부터 건축물까지 출입로 폭은 건축물 주출입구 폭 이상이어야 한다":"단지 안 도로에서 건축물로 가는 출입로 폭은 건축물의 주출입구 폭 이상이어야 해요.","단지 내에서 원활하되 통과교통에 쓰이지 않아야 한다":"주구 안 교통은 원활해야 하되 밖에서 들어온 차가 그냥 지나가는 통과교통에 쓰이면 안 됩니다.","단지 밖 간선시설부터 단지 경계선까지를 설치범위로 한다":"상하수도 간선시설은 단지 밖 간선부터 단지 경계선까지 설치합니다.","단지의 기간도로 접속 폭은 6m 이상이다":"기간도로에 단지가 이어지는 폭의 기준이 6m 이상이라는 말이에요.","대구는 업무·첨단·패션산업, 광주는 첨단산업·예술문화, 대전은 행정·과학연구·첨단산업으로 특화했다":"이 계획은 도시마다 맡을 기능을 달리 정해, 대구에는 패션산업을, 대전에는 행정과 과학연구를 두었습니다.","대규모 도시·공장·노동력으로 규모의 경제를 추구하며 국가가 주도적으로 경제를 발전시켰다":"포디즘은 대규모 도시, 공장, 노동력으로 규모의 경제를 노렸고 국가가 경제 발전을 이끌었습니다.","대도시·거대도시·세계도시 등으로 구분했으며 성장도시는 없다":"독시아디스는 도시를 대도시, 거대도시, 세계도시 등으로 나누었고 성장도시라는 구분은 없습니다.","대도시에 인구·산업을 더 집중시키려는 것은 신도시 개발 목적이 아니다":"대도시에 인구와 산업을 더 모으려는 것은 신도시를 개발하는 목적이 아닙니다.","대로 1류는 35m 이상 40m 미만, 중로 3류는 12m 이상 15m 미만이다":"도로는 폭에 따라 류로 나뉘며 대로 1류는 35m 이상 40m 미만, 중로 3류는 12m 이상 15m 미만입니다.","대수곡선이라 부르지는 않는다":"이 곡선을 대수곡선이라고 부르지는 않아요.","대전·부산·광주생활권이 있고 인천생활권은 없다":"대도시 생활권 후보는 대전, 부산, 광주이고 인천은 제외되어 있습니다.","대중교통 지향 개발, 직주근접, 개발권양도를 통한 녹지 보전":"토지이용 면에서는 대중교통 지향 개발, 직장과 집을 가깝게 두기, 개발권양도로 녹지 지키기를 들 수 있습니다.","대지가 녹지지역과 다른 지역에 걸치면 각 지역 규정을, 방화지구에 걸치면 전부 방화지구 규정을 적용한다":"대지가 여러 지역에 걸치면 각각 규정을 따르되, 방화지구에 걸치면 전체에 방화지구 규정을 적용합니다.","대지조성사업지구, 관광특구, 택지개발예정지구는 제1종 지구단위계획구역으로 지정할 수 있다":"택지개발예정지구나 관광특구 같은 곳은 첫째 유형의 구역으로 묶어 계획을 세울 수 있습니다.","대지 효용 증진과 공공시설 정비를 위한 것으로 기존 권리를 인정한다":"대지의 효용을 높이고 공공시설을 정비하려는 사업으로 기존 권리를 인정합니다.","대체로 수출산업이며 제조업이 주종을 이루고 외부에서 화폐를 벌어들인다":"기반산업은 밖으로 파는 수출산업이 중심이라 제조업이 많고 지역 밖에서 돈을 들여옵니다.","대학·산업대학·교육대학·전문대학은 인구집중유발시설에 해당한다":"대학, 산업대학, 교육대학, 전문대학은 사람을 몰리게 하는 인구집중유발시설에 해당합니다.","대형가구·고층 위주 개발은 우리나라 주거단지 개선 방안이 아니다":"큰 가구에 높은 건물 위주로 개발하는 것은 우리나라 주거단지를 고치는 방안이 아닙니다.","델파이법·시나리오작성법·브레인스토밍 같은 정성적 기법도 쓰인다":"지역계획을 세울 때는 델파이법, 시나리오작성법, 브레인스토밍 같은 질적 기법도 씁니다.","델파이법은 익명성 덕분에 심리적 교란 염려가 크지 않다":"델파이법은 응답자를 드러내지 않아서 심리적으로 영향을 받을 염려가 크지 않아요.","도농 균형발전, 산업의 조화 배치, 안전하고 풍요로운 국토환경 조성":"도시와 농촌이 균형 있게 발전하고 산업을 조화롭게 배치하며 안전하고 풍요로운 국토환경을 만드는 것이 목적입니다.","도로 개방감을 위해 건축물을 일정거리 후퇴시켜 지정하며 후퇴 공지 조성지침도 세운다":"건축한계선은 도로가 시원하게 보이도록 건물을 일정 거리 물려 짓게 하는 선이며, 그 공지를 만드는 지침도 둡니다.","도로망은 토지 접근성과 이동성을 동시에 고려하며 기능·교통량에 따라 횡단면을 정한다":"도로망은 땅에 닿기 쉬운 접근성과 빨리 움직이는 이동성을 함께 따지며, 기능과 교통량에 맞춰 횡단면을 정해요.","도로·상하수도 등 사회간접시설 설치는 수도권정비계획의 내용이 아니다":"도로나 상하수도를 설치하는 일은 수도권정비계획이 다룰 내용이 아닙니다.","도로율이 용도지역별 기준보다 20% 이상 미달하거나 도로서비스 수준이 낮은 지역이 대상이다":"도로율이 기준보다 20% 이상 모자라거나 도로 서비스 수준이 낮은 곳이 개발밀도관리구역 대상입니다.","도로폭보다 작은 점포폭이 반복될 때 가로가 활기 있다고 했다":"아시하라는 도로폭보다 좁은 점포폭이 이어질 때 가로가 활기 있다고 했습니다.","도로·하수도 등 기반시설을 계획 내용에 맞춰 쉽게 배치할 수 있다":"PUD에서는 도로와 하수도 같은 기반시설을 계획 내용에 맞게 쉽게 배치할 수 있어요.","도로·하천·하수도는 산업단지 개발 시 국가·지자체에 무상 귀속되는 시설이며 쓰레기소각장은 유상이다":"도로, 하천, 하수도는 개발되면 국가와 지자체에 공짜로 넘어가는 시설이고 쓰레기소각장은 돈을 받고 넘기는 시설이에요.","도시개발구역을 지정하려면 미리 주민의 의견을 청취해야 한다":"도시개발구역을 지정하려면 먼저 주민의 의견을 들어야 해요.","도시경제의 구성요소와 분석에 관한 이론":"실체적 이론은 도시경제를 이루는 요소와 그 분석을 다루는 이론입니다.","도시계획가의 GIS 활동은 측정·도면화·모형화·관리의 4M으로 요약된다":"도시계획가가 하는 GIS 활동은 측정, 도면화, 모형화, 관리의 4M으로 요약해요.","도시계획시설 결정 고시 후 1단계·2단계로 나누어 3년 이내로 수립한다":"도시계획시설을 결정·고시하고 나면 1단계와 2단계로 나눈 집행계획을 3년 안에 세웁니다.","도시계획으로 결정하며 2 이상 도에 걸친 협의 불성립 시 중앙정부가 조정한다":"조성계획은 도시계획으로 정하며, 둘 이상 도에 걸쳐 협의가 안 되면 중앙정부가 조정합니다.","도시 고유의 역사·문화가 강조되고 다양한 이미지 전략이 쓰인다":"세계화 시대에는 도시마다 고유의 역사와 문화를 내세우고 다양한 이미지 전략을 씁니다.","도시공간을 자본 축적·재생산의 장소로만 보는 것은 포스트모던이 아니라 구조주의적 관점이다":"도시공간을 자본이 쌓이고 되풀이되는 장소로만 보는 것은 구조주의적 관점입니다.","도시공원·녹지·유원지, 녹지가 조성된 광장·보행자도로, 식생 공간":"공원녹지는 공원, 녹지, 유원지는 물론 녹지가 있는 광장과 보행로, 식생 공간까지 아우릅니다.","도시공원 면적기준의 빈칸은 6㎡와 3㎡로 채워진다":"공원 면적기준 표에서 비어 있던 자리에는 6㎡와 3㎡가 들어갑니다.","도시관리계획으로 설치되며 민간의 참여도 제한되지 않는다":"기반시설은 도시관리계획으로 설치하며 민간 참여도 막지 않아요.","도시관리계획의 상위계획으로 물적 측면과 사회·경제적 측면을 포괄한다":"도시관리계획의 상위에 있으며 물적 측면과 사회·경제적 측면을 모두 아우릅니다.","도시·관리·농림·자연환경보전지역이며 자연환경정비지역은 아니다":"용도지역은 도시, 관리, 농림, 자연환경보전지역의 네 가지이고 자연환경정비지역은 없습니다.","도시교통시설지역은 다핵심이론이 제시한 기능지역이 아니다":"도시교통시설지역은 다핵심이론에서 말하는 기능지역이 아닙니다.","도시 기능을 원활하게 하고 풍요롭고 양호한 환경을 만든다":"도시계획은 도시 기능이 원활하게 돌아가도록 하고 풍요롭고 좋은 환경을 만듭니다.","도시 기능을 주거·노동·위락·교통 4가지로 구분했으며 공공은 포함되지 않는다":"아테네헌장은 도시 기능을 주거, 노동, 위락, 교통의 4가지로 나누었고 공공은 넣지 않았어요.","도시 내부구조가 아니라 도시 간 계층구조를 설명하는 이론이다":"중심지이론은 도시 안의 구조가 아니라 도시들 사이의 계층 구조를 설명합니다.","도시는 교통축을 따라 도심에서 외곽으로 부채꼴 모양으로 분화된다":"도시는 교통축을 따라 도심에서 밖으로 부채꼴 조각처럼 갈라진다는 이론이에요.","도시는 이질적이고 익명적인 집단의 성격이 강하다":"도시 사람들은 서로 성격이 다르고 얼굴을 알지 못하는 익명적 집단에 가깝습니다.","도시를 주민 대부분이 상공업적 영리수입으로 생활하는 정주지로 정의했다":"베버는 도시를 주민 대다수가 장사와 공업으로 먹고사는 곳이라고 정의했습니다.","도시미관을 높이고 설비 갱신을 쉽게 한다":"공동구는 도시 미관을 해치지 않고 설비를 교체하기 쉽습니다.","도시 상주인구가 증가하는 것이 아니라 감소하는 현상이다":"역도시화는 도시 인구가 늘어나는 것이 아니라 줄어드는 현상입니다.","도시생태학에 기반하며 활동이 주요 교통로를 따라 이루어진다고 보지는 않는다":"도시생태학에 바탕을 둔 이론이며 활동이 주요 교통로를 따라 이뤄진다고 보지는 않아요.","도시설계 요소에는 토지이용, 건물형태와 매싱, 보존이 있다":"쉬라바니가 꼽은 도시설계 요소는 토지이용, 건물형태와 매싱, 보존 등입니다.","도시 성장은 기반산업의 성장이 주도하며 수출은 재화뿐 아니라 서비스도 포함한다":"도시는 기반산업이 커질 때 성장하고, 여기서 수출에는 재화뿐 아니라 서비스도 들어갑니다.","도시와 농촌이 통합·개발되도록 생산 다양화, 자원 공영제, 기회 균등을 중시한다":"도농접근법은 도시와 농촌을 한 틀로 개발하려고 생산의 다양화, 자원의 공공 이용, 기회 균등을 내세웁니다.","도시의 무질서한 확산 방지, 자연환경 보전, 보안상 필요가 있으면 개발제한구역을 지정한다":"도시가 무질서하게 퍼지는 것을 막고 자연환경을 보전하며 보안상 필요가 있을 때 개발제한구역을 지정해요.","도시이미지 요소는 통로·지구·결절점(에지·랜드마크 포함)이며 광장은 아니다":"도시이미지 요소는 통로, 지구, 결절점이며 에지와 랜드마크도 있지만 광장은 요소가 아닙니다.","도시재생 활성화 및 지원에 관한 특별법에 근거한다":"도시재생은 도시재생 활성화 및 지원에 관한 특별법을 근거로 합니다.","도시 전체가 아닌 특정 지구를 대상으로 하며 3차원적 요소에도 관여한다":"지구단위계획은 도시 전체가 아니라 특정 지구를 대상으로 하고, 입체적인 요소까지 다룹니다.","도시 전체의 기본 구조를 중시한다":"하향적 접근은 도시 전체의 기본 구조를 먼저 중시해요.","도시정부가 주체가 되어 공간 그 자체를 상품화한다":"도시정부가 앞장서서 공간 자체를 상품처럼 팔아 보는 전략이에요.","도시지역 내 도시공원은 주민 1인당 6㎡ 이상을 확보해야 한다":"도시지역 안에서는 주민 한 사람당 6㎡ 이상의 도시공원을 확보해야 합니다.","도시지역에서 무게 50t·부피 50㎥·수평투영면적 25㎡ 이하 공작물 설치":"무게 50t, 부피 50㎥, 수평투영면적 25㎡ 이하의 공작물은 도시지역에서 허가 없이 설치할 수 있어요.","도시첨단산업단지의 지정 제외 지역은 특별시와 광역시 전체가 아니다":"특별시와 광역시라고 해서 도시첨단산업단지 지정에서 통째로 빠지는 것은 아닙니다.","도시 하부구조에 관심을 두고 상대적으로 정밀도가 높으며, 상부구조 위주는 아니다":"도시설계는 하부구조에 관심을 두는 정밀한 작업이고 상부구조 중심이 아닙니다.","도시활동을 생활·생산·위락으로 구분했으며 생산과 소비로 나눈 것은 부정확하다":"게데스는 도시활동을 생활, 생산, 위락으로 나누었고 생산과 소비로 나눴다고 하면 맞지 않아요.","도심 고밀화, 교통센터 집중, 충분한 공지·공원 확보가 특징이며 그린벨트 설치는 포함되지 않는다":"이 도시는 도심을 높고 빽빽하게 하고 열린 땅을 넉넉히 확보했으며 그린벨트는 두지 않았습니다.","도심 근처에 고층건물이 집중하고 외곽으로 갈수록 건물높이가 낮아진다":"단일도심도시에서는 도심 가까이에 고층건물이 몰리고 바깥으로 갈수록 건물이 낮아집니다.","도심에 주거기능을 더해 도심공동화를 막고 활력을 준다":"도심에 주거기능을 더하면 도심이 텅 비는 것을 막고 활력을 줍니다.","독립적으로 수익성을 가진 3개 이상의 용도를 수용해야 한다":"MXD는 따로 떼어도 수익이 나는 용도를 3개 이상 담아야 합니다.","독일의 지구상세계획(B-Plan), 일본의 지구계획제도 영향을 받았다":"우리나라 도시설계는 독일 B-Plan과 일본 지구계획제도를 참고했어요.","동경은 임해부 부도심 기반구조형, 런던은 도시재개발형, 뉴욕은 정보통신 산업단지형 텔레포트다":"도쿄는 임해부 부도심, 런던은 도시재개발, 뉴욕은 정보통신 산업단지라는 서로 다른 형으로 텔레포트가 조성됐습니다.","동심원이론에 교통망의 중요성과 방향성을 더한 것이며, 도심에 고급주택지가 있다고 보지는 않는다":"호이트는 동심원이론에 교통망이라는 방향성을 보태 설명했으며, 고급주택지가 도심에 있다고는 안 봤습니다.","동일한 노동생산성, 동일한 소비수준, 폐쇄된 경제를 가정한다":"노동생산성이 같고 소비수준이 같으며 폐쇄된 경제를 가정합니다.","동일한 생산비를 가정하는 것은 아니다":"수출기반모형은 생산비가 같다고 가정하지는 않아요.","동질의식 함양, 소속감 고취, 이웃 간 교류 촉진이다":"동질의식을 기르고 소속감을 높이며 이웃끼리 오가도록 하는 것이 사회적 측면의 목표입니다.","동질적인 토지이용을 포함하고 행정구역과 가급적 일치시킨다":"교통존은 토지이용이 비슷한 곳끼리 묶고 가능하면 행정구역과 맞춥니다.","동질지역을 규명하는 기법이 아니다":"상관분석은 동질지역을 규명하는 기법에 들지 않아요.","두 시점 자료만 있어도 저렴하게 동태적 분석이 가능하다":"두 시점의 자료만 있어도 적은 비용으로 변화를 동태적으로 분석할 수 있어요.","두 중심지 간 흐름이 중심지 크기에 비례한다":"소매인력법칙에서 두 중심지 사이 흐름은 중심지의 크기에 비례합니다.","등고선·가시도·패턴(유형) 분석이며 인지도분석은 사회적 분석이다":"지형분석은 등고선, 가시도, 패턴(유형) 분석이고 인지도분석은 사회적 분석에 속해요.","등고선 간격이 클수록 경사는 완만하며 등고선은 폐곡선을 이룬다":"등고선 간격이 넓을수록 경사가 완만하고, 등고선은 닫힌 곡선을 이룹니다.","등고선에 직각이 아니라 평행하게 배치하는 것이 효율적이다":"접근 도로는 등고선에 직각으로 내는 것보다 평행하게 내는 것이 효율적이에요.","등고선은 절벽을 제외하면 서로 교차하지 않는다":"등고선은 절벽을 빼면 서로 만나거나 겹쳐지지 않습니다.","래드번은 자동차 도로를 일원화하거나 주거단지 내 통과교통을 허용하지 않는다":"래드번은 자동차 도로를 하나로 합치거나 주거단지 안의 통과교통을 허용하지 않았습니다.","랜드마크, 경계(Edge), 지구(District)는 린치의 도시이미지 구성요소이며 Zone은 아니다":"랜드마크와 경계와 지구는 린치의 구성요소에 들지만 Zone이라는 요소는 없어요.","런던 주변의 초기 뉴타운으로 주택지를 4개 그룹으로 나눠 근린주구를 배치했다":"할로우는 런던 주변의 초기 뉴타운으로 주택지를 4개 그룹으로 나누어 근린주구를 놓았습니다.","레치워스·웰윈 건설로 본격화되었고 위성도시·신도시 개발에 영향을 미쳤다":"레치워스와 웰윈을 건설하면서 본격화되어 위성도시와 신도시 개발에 영향을 줬습니다.","로렌츠곡선·지니계수·쿠즈네츠비":"지역소득격차는 로렌츠곡선, 지니계수, 쿠즈네츠비로 잴 수 있어요.","매개변수 q값이 1보다 크면 도시규모 분포가 종주화 상태임을 뜻한다":"매개변수 q가 1보다 크면 큰 도시 하나에 쏠리는 종주화 상태를 뜻해요.","면적에 비례한 인센티브는 정량적, 지침 준수에 따른 인센티브는 정성적 인센티브라 한다":"면적에 비례해 주는 인센티브는 정량적이고, 지침을 지키면 주는 인센티브는 정성적이라고 해요.","면적을 10% 축소했다가 다시 20% 확대해 전체 10% 늘리는 조합은 경미한 변경이 아니다":"면적을 10% 줄였다가 20% 늘려 합계가 10% 늘어난 경우는 단계별로 따지면 경미한 변경이 아닙니다.","모든 주민에게 균등한 접근성을 주고 수요 변화에 대한 융통성이 있다":"노선형은 모든 주민이 고르게 접근할 수 있고 수요가 달라져도 대응하기 쉽습니다.","목적 달성을 위한 대안을 평가·선택하고 예산 배분을 합리화하는 도구다":"PPBS는 목적을 이루기 위한 대안을 평가하고 골라 예산 배분을 합리화하는 도구입니다.","목표설정단계는 계획의 전제 목표를 세우는 단계":"목표설정단계는 계획의 바탕이 될 목표를 정하는 첫 단계예요.","묘지공원·근린공원·어린이공원·체육공원은 도시공원 및 녹지법상 도시공원이다":"도시공원 및 녹지법이 도시공원으로 꼽는 것은 묘지, 근린, 어린이, 체육공원 등이에요.","묘지공원·문화공원·수변공원이고, 도시자연공원은 주제공원이 아니다":"주제공원은 묘지, 문화, 수변공원으로 나뉘고 도시자연공원은 따로 취급합니다.","묘지공원·문화공원·수변공원이며 어린이공원은 생활권공원이다":"주제공원은 묘지공원, 문화공원, 수변공원이고 어린이공원은 생활권공원이에요.","무관심한 사람들의 이익까지 대변하는 것은 교류적 계획이 아니라 옹호적 계획의 특징이다":"교류적 계획이 아니라 옹호적 계획이 무관심한 사람들의 몫까지 대신 말해 줍니다.","무분별한 도시 확산의 대안으로 등장해 압축적·복합적 토지이용을 추구한다":"무분별하게 퍼지는 도시 확산의 대안으로 나타나 압축적이고 복합적인 토지이용을 추구해요.","무역·상업활동과 공동체 자율성을 강조했다":"베버는 무역과 상업활동, 그리고 공동체의 자율성을 강조했어요.","문화재 출토는 시장위험이 아니라 건설관련위험이다":"문화재가 땅에서 나오는 일은 팔리는 문제가 아니라 공사를 하다 생기는 건설관련위험입니다.","문화적 서비스는 임의적 서비스이며 경찰·소방서비스는 기본적(필수) 서비스다":"경찰과 소방은 반드시 제공해야 하는 기본적 서비스이고 문화 서비스는 하고 안 하고를 정하는 임의적 서비스입니다.","문화적 요인은 샤핀이 제시한 분류에 포함되지 않는다":"문화적 요인은 샤핀이 제시한 분류에 들어가지 않아요.","물리적 환경 요소를 유기적으로 통합해 쾌적한 도시환경을 조성한다":"도시설계는 물리적 환경 요소를 유기적으로 묶어 쾌적한 도시환경을 만듭니다.","민간시설을 직접 유지관리하는 것은 도시정부의 기능이 아니다":"민간 건물을 정부가 직접 관리하는 일은 도시정부가 맡는 기능이 아닙니다.","민간의 참여도 가능하며 정부만 직접 설치하는 것은 아니다":"도시계획시설은 정부만 짓는 것이 아니고 민간이 참여해 설치할 수도 있어요.","반경 1/4마일 보행중심 커뮤니티와 좁은 격자형 가로로 교통량을 분산시킨다":"TND는 반경 4분의 1마일의 걷기 중심 커뮤니티와 좁은 격자형 길로 교통량을 나눕니다.","반송파 위상관측법만 있는 것이 아니라 여러 방법이 있다":"위치를 정하는 방법에는 반송파 위상관측법 말고도 여러 가지가 있어요.","방사환상형은 인구 10만 이상 신도시보다는 대도시에 적합하다":"방사환상형은 큰 도시에 더 알맞고, 인구 10만 이상 신도시에는 덜 맞습니다.","방식마다 공통 적용되지 않으며, 대규모 소유자의 소유권 침해가 큰 것도 아니다":"감보율이 모든 방식에 똑같이 적용되는 것은 아니며, 대규모 소유자의 소유권을 크게 침해하는 것도 아닙니다.","방음·방습성은 지하철·통신시설, 방폭성은 폭파실험·석유비축시설과 연결된다":"방음과 방습은 지하철과 통신시설에, 폭발을 견디는 성질은 폭파실험과 석유비축시설에 연결됩니다.","방재녹지·차폐녹지라는 세분은 없으며 완충·경관·연결녹지로 나뉜다":"방재녹지와 차폐녹지라는 세분은 없고 완충, 경관, 연결녹지로 나뉘어요.","방재효율이 향상되고 유지관리비가 절감된다":"한곳에 모아 두니 재난에 대응하기 좋고 유지관리비가 줄어요.","버제스가 시카고를 연구해 경험적으로 제시한 5개 지대 구조다":"버제스는 시카고를 연구해 경험으로 5개 동심 지대 모형을 만들었어요.","법령상 금지된 행위를 해제해 적법하게 하는 것이다":"허가는 법령으로 금지된 행위를 풀어 주어 적법하게 하는 행정행위입니다.","법인으로 설립할 수 있으며 명칭에 '정비사업조합'을 사용해야 한다":"정비사업조합은 법인으로 세울 수 있고 이름에 '정비사업조합'이라는 말을 써야 합니다.","벽면 비율의 균일성 확보, 어지러운 스카이라인 방지, 이면도로 과부하 방지를 위해 필요하다":"벽면 비율을 고르게 하고 어지러운 스카이라인을 막고 이면도로에 부하가 걸리는 것을 막으려고 최고높이를 규제해요.","변이할당분석, 경제기반이론, 헤롯-도마모델은 지역경제 성장을 예측하는 이론이다":"변이할당분석, 경제기반이론, 헤롯-도마모델은 지역경제가 얼마나 클지를 내다보는 이론입니다.","변장 측정값에도 오차가 따르며, 좌표는 Xc=XA+SAC·cosTAC, Yc=YA+SAC·sinTAC로 구한다":"변의 길이를 잰 값에도 오차가 있으며, 좌표는 출발점 좌표에 변장과 방향각의 삼각함수 곱을 더해 구합니다.","별도 종류가 아니라 노외주차장의 한 형태다":"지하주차장은 따로 있는 종류가 아니라 노외주차장 가운데 한 형태예요.","보상비용이 과다할 수 있어 많은 준비와 기획이 필요하다":"보상비용이 지나치게 커질 수 있어 준비와 기획이 많이 필요한 것이 단점이에요.","보상지역지구제(인센티브조닝), 개발권이양(TDR), 계획단위개발(PUD)은 유도적 성격이 강한 제도다":"보상지역지구제, 개발권이양, 계획단위개발은 규제보다 유도하는 성격이 강한 제도입니다.","보아잔 계획은 멈포드가 아니라 르꼬르뷔제의 작품이며, 근린주구단위는 페리의 개념이다":"보아잔 계획을 만든 이는 르꼬르뷔제이지 멈포드가 아니며, 근린주구단위를 말한 이는 페리입니다.","보전관리·생산관리·계획관리지역으로 나뉘며 자연환경보전지역은 별도 용도지역이다":"관리지역은 보전관리, 생산관리, 계획관리로 나뉘고 자연환경보전지역은 따로 있는 용도지역입니다.","보전녹지라는 세분은 없으며 자연환경 보전은 완충녹지가 아니라 경관녹지의 기능이다":"자연환경 보전은 경관녹지가 하는 일이며, 보전녹지라는 세분은 없고 완충녹지의 일도 아닙니다.","보전용지·시가화용지·시가화예정용지":"토지이용계획의 용도 구분은 보전용지, 시가화용지, 시가화예정용지예요.","보존가치가 낮게 평가되거나 집단거주 취락의 주거환경 개선이 필요하면 구역을 조정·해제할 수 있다":"보존할 가치가 낮다고 평가되거나 집단 취락의 주거환경을 개선해야 하면 구역을 조정하거나 해제할 수 있습니다.","보존지구, 역사문화미관지구, 최고고도지구를 지정할 수 있다":"전통건조물과 문화재를 보전하려면 보존지구, 역사문화미관지구, 최고고도지구를 지정할 수 있어요.","보·차도는 분리를 원칙으로 하고 오픈스페이스는 구상 단계부터 공원·보행로·학교와 연결한다":"보도와 차도는 나누는 것이 원칙이고, 오픈스페이스는 구상 단계부터 공원, 보행로, 학교와 이어 둡니다.","부드빌·요인분석법·베리는 동질성 원칙과 관련되며 누스는 아니다":"부드빌과 베리 등이 동질성 원칙 쪽 학자이고, 누스는 이 원칙과 관련이 없습니다.","부설주차장은 당해 시설물 이용자만이 아니라 일반에게도 제공될 수 있다":"부설주차장은 해당 시설 이용자뿐 아니라 일반 사람에게도 열어 줄 수 있습니다.","부외금융 효과가 있고 신용이 낮아도 자금을 조달할 수 있으며 운용보수는 낮다":"자산담보부증권은 장부 밖 금융 효과가 있고 신용이 낮아도 자금을 모을 수 있으며 운용보수는 낮습니다.","부지 내 위치 변경, 초과 설치분 확인, 차량통행 금지로 이용 불가한 경우":"부지 안에서 위치를 옮기거나, 초과 설치분임을 확인하거나, 차량 통행이 막혀 못 쓰게 된 경우에는 용도변경이 됩니다.","부호·크기가 불규칙하고 정(+)·부(-) 오차 발생확률이 같다":"우연오차는 부호와 크기가 제멋대로이고 플러스와 마이너스가 나올 확률이 같습니다.","분리된 필지를 기본으로 주택을 배치하는 것은 PUD의 특징이 아니다":"필지를 따로따로 나눠 그 위에 주택을 놓는 것은 PUD의 방식이 아닙니다.","분산·기능분리하는 것이 아니라 집적시켜 효율을 높인다":"압축도시는 토지이용을 흩어 놓거나 기능을 나누지 않고 모아 효율을 높입니다.","분산배치형은 이 분류에 포함되지 않는다":"분산배치형이란 갈래는 텔레포트단지 분류에 없어요.","분석방법을 예산·계획 과정에 적용하는 시스템이지 경제원리를 무시하는 것이 아니다":"PPBS는 분석 기법을 예산과 계획에 접목한 체계이며 경제원리를 외면하지 않아요.","분석자료가 적게 들지만 기반·비기반 활동을 구분하기는 쉽지 않다":"필요한 자료가 적다는 장점이 있지만 어느 활동이 기반이고 비기반인지 가르기는 어렵습니다.","분양설계, 보류지 명세·추산가액, 분양대상자별 추산액이 포함된다":"관리처분계획서에는 분양설계, 보류지 명세, 추산가액, 분양대상자별 추산액이 적힙니다.","브라질리아·캔버라·컴버놀드이며 로스앤젤레스는 아니다":"계획된 신도시로는 브라질리아, 캔버라, 컴버놀드가 있고 로스앤젤레스는 아닙니다.","비경합성·비배제성 때문에 무임승차 문제를 낳는다":"공공재는 경합하지 않고 배제할 수 없어서 무임승차 문제가 생깁니다.","비오톱 조성, 투수성 바닥처리, 자원 재활용":"비오톱을 만들고 물이 스며드는 바닥으로 처리하고 자원을 재활용하는 것이 친환경 계획이에요.","비용을 줄이려면 이동경로를 최소화하고 간선·지선을 구별해 배치하며 완만한 구배를 쓴다":"이동 경로를 줄이고 간선과 지선을 나누어 완만한 구배로 배치해야 비용이 줄어듭니다.","사람이 고통을 느끼기 시작하는 소리 세기는 약 140dB이다":"소리가 약 140dB에 이르면 사람이 아픔을 느끼기 시작해요.","사리사욕 추구행위 자체는 시장실패의 요인으로 분류되지 않는다":"자기 이익을 추구하는 행위 자체는 시장실패의 요인으로 보지 않아요.","사변형삼각망은 조건식이 많아 정밀도가 가장 높고, 단열삼각망은 도로·하천 측량에 쓰인다":"사변형삼각망은 조건식 수가 많아 가장 정밀하고, 단열삼각망은 폭이 좁고 긴 구간 측량에 알맞습니다.","사업계획 승인이 취소된 후 6개월이 지나지 않으면 동일 시설업 승인을 다시 받을 수 없다":"승인이 취소되고 반년이 지나기 전에는 같은 시설업으로 다시 승인받지 못해요.","사업 시행 이전에 사전적으로 이루어지며 목적 충족 여부로 판단한다":"타당성분석은 사업을 시작하기 전에 목적을 이룰 수 있는지를 따져 보는 작업입니다.","사업 자산과 현금흐름을 담보로 하며 모기업에 대한 소구권이 배제·제한된다":"PF는 사업의 자산과 현금흐름을 담보로 하며 모기업에 대한 상환 청구권은 없거나 제한됩니다.","사적 공간 확대나 도시공간 위계 파괴를 통한 자유로운 토지이용은 뉴어바니즘의 목표가 아니다":"사적 공간을 넓히거나 도시공간의 위계를 깨고 자유롭게 토지를 쓰는 것은 뉴어바니즘의 목표가 아닙니다.","사진에 의한 방법, 메쉬(mesh)법, 기호화 방법":"경관을 분석하는 기법에는 사진법, 메쉬법, 기호화 방법이 있습니다.","사회·경제적 여건 변화에 따라 변경되어야 하며 고정불변은 아니다":"최저주거기준은 사회·경제 여건이 달라지면 바꿔야 하고 한 번 정하면 그대로 두는 값이 아닙니다.","사회 인구학적 요인은 이 세 요인에 포함되지 않는다":"사회 인구학적 요인은 이 세 요인에 들어가지 않아요.","사회적 지속성에는 문화·역사·제도, 환경적 지속성에는 환경의 질·생태계 용량·자연자원이 포함된다":"사회적 지속성은 문화와 역사와 제도까지, 환경적 지속성은 환경의 질과 생태계 용량과 자연자원까지 넓게 포괄합니다.","산림·상수원 보호, 농경지 보전, 무질서한 평면적 확산 방지를 목적으로 한다":"개발제한구역은 산림과 상수원을 지키고 농경지를 보전하며 도시가 무질서하게 퍼지는 것을 막으려는 제도입니다.","산업(Industrial), 학술(Academic), 주거(Habitation) 3대 존으로 구성된다":"테크노폴리스는 산업(Industrial), 학술(Academic), 주거(Habitation)의 세 구역으로 이루어집니다.","산업교역형·지식기반형·관광레저형이며 특성화형은 없다":"기업도시는 산업교역형, 지식기반형, 관광레저형이 있고 특성화형은 없습니다.","산업구조, 노동의 질, 노동참여율은 지역소득격차를 낳는 외생변수다":"산업구조와 노동의 질과 노동참여율은 바깥에서 주어져 소득 격차를 만드는 원인 변수예요.","산업구조 특성, 지리적 조건, 지역간 인구특성 차이":"산업구조의 특성, 지리적 조건, 지역 간 인구특성 차이가 지역문제를 일으키는 직접 요인입니다.","산업단지개발사업도 노외주차장을 의무적으로 설치해야 한다":"산업단지개발사업도 노외주차장을 의무적으로 만들어야 하는 대상이에요.","산업 상호간의 연관성은 파악할 수 없다":"산업끼리 서로 어떻게 연결되어 있는지는 파악하지 못하는 한계가 있습니다.","산업입지공급계획에는 지역별·유형별 공급사항과 지원사항이 포함된다":"산업입지공급계획에는 지역별과 유형별 공급 내용, 그리고 지원 내용이 들어갑니다.","산업입지론은 최소비용·이윤극대화·최대수입(시장지역) 접근법이다":"산업입지론의 접근법은 최소비용, 이윤극대화, 최대수입(시장지역) 세 가지입니다.","산업 정체로 인한 고용 감소는 과밀도시가 아니라 쇠퇴형 도시의 문제다":"산업이 정체되어 고용이 줄어드는 것은 과밀도시가 아니라 쇠퇴하는 도시의 문제입니다.","산업혁명을 의식한 이상도시 쇼(Chaux)":"클로드 니콜라 르두는 산업혁명을 의식해 쇼(Chaux)라는 이상도시를 설계했습니다.","산정 방법에 따라 필요 상업면적 추계가 달라진다":"어떤 산정 방법을 쓰느냐에 따라 필요한 상업면적의 추계가 달라집니다.","상권 활성화, 토지의 효율적 이용, 도시기능 회복을 위해 필요하다":"도시환경정비사업은 상권을 살리고 토지를 효율적으로 쓰며 도시기능을 되찾으려고 합니다.","상류층의 거주지 선택 능력이 도시 거주지 유형을 결정한다고 본다":"호이트는 상류층이 어디에 살기로 고르느냐가 도시 거주지의 유형을 정한다고 봤습니다.","상세계획처럼 대단위 용도지역을 변경할 수는 없다":"상세계획과 달리 큰 단위의 용도지역을 바꿀 수는 없어요.","상수도·공동구·방송통신시설이며 하수도는 환경기초시설이다":"유통·공급시설에 들어가는 것은 상수도, 공동구, 방송통신시설이며 하수도는 환경기초시설 쪽입니다.","상업시설 이용확률이 시설 크기에 비례하고 거리에는 반비례한다고 본다":"Huff모형은 상업시설을 이용할 확률이 시설이 클수록 높고 멀수록 낮다고 봅니다.","상위계획의 지침을 받아 도시 기본계획을 세우는 것도 상향적 접근이 아니라 하향적 접근이다":"위의 지침을 받아 도시기본계획을 만드는 일은 아래에서 올라가는 상향적 접근이 아니라 하향적 접근이에요.","상위용도를 하위용도로부터 보호하는 누적식 지역제이며 필지 단위로 규제한다":"유클리드 지역제는 상위 용도를 하위 용도로부터 지키는 누적식이며 필지 단위로 규제합니다.","상정인구밀도에 의한 방법은 상업용지 산정에 일반적으로 쓰이지 않는다":"상정인구밀도를 써서 상업용지를 구하는 방법은 흔히 쓰지 않아요.","상환 의무가 없으나 회사 통제권 일부를 포기해야 한다":"지분으로 자금을 모으면 갚을 필요는 없지만 회사의 통제권 일부를 내줘야 해요.","생산공간과 연구개발 공간은 독립적으로 분리하지 않고 연계해 배치한다":"생산공간과 연구개발 공간을 따로 떼어 놓지 않고 이어서 배치해요.","생산요소의 자유로운 지역간 이동으로 지역간 형평이 달성된다고 보는 것은 신고전학파 이론이다":"생산요소가 지역 사이를 자유롭게 오가면 지역 간 형평이 이뤄진다고 보는 쪽이 신고전학파입니다.","생애주기별 순차 재개발이 아니라 순환용 주택에 임시 이주시킨 뒤 순차적으로 재개발하는 방식이다":"순환재개발은 순환용 주택에 임시로 이주시킨 뒤 차례로 재개발하는 방식이며 생애주기에 따른 것이 아닙니다.","생태계 파괴·환경오염 예방과 사회간접자본 비용 축소를 성장관리의 필요성으로 들었다":"데그로브는 생태계 파괴와 환경오염을 막고 사회간접자본 비용을 줄이는 것을 성장관리가 필요한 이유로 들었어요.","생태적 접근은 맥하그, 행태적 접근은 알트만, 심리적 접근은 에드워드 홀과 연결된다":"맥하그는 생태적, 알트만은 행태적, 에드워드 홀은 심리적 접근과 짝을 이룹니다.","생태환경 가치는 공업 집중을 촉진하는 인자가 아니다":"생태환경이 좋다는 이유로 공업이 한 곳에 모여드는 것은 아닙니다.","생활권(근린주구)은 도시의 3대 구성요소에 포함되지 않는다":"생활권(근린주구)은 도시의 3대 구성요소에 들어가지 않아요.","생활양식의 변화는 정성적 요소로 정량적 예측변수가 아니다":"생활양식의 변화는 숫자로 바로 잴 수 없어서 정량적 변수로 보지 않습니다.","생활의 풍요로움, 자발적 활동, 자유감을 준다":"오픈스페이스는 시민에게 생활의 풍요로움과 자발적 활동, 자유로운 느낌을 줍니다.","생활환경시설 부족, 교통·공해, 경관 혼란·획일화 문제를 겪는다":"급성장한 대도시는 생활환경시설이 모자라고 교통과 공해가 심하며 경관이 어수선하고 획일화됩니다.","서울특별시장이 아니라 시·도지사가 지정한다":"도시첨단산업단지는 서울특별시장이 아니라 시·도지사가 지정해요.","선순위 채권이 PF 자금원 중 가장 큰 비중을 차지하며 대부분 상업은행 차입금이다":"PF 자금원 중 선순위 채권의 비중이 가장 크고 대부분은 상업은행에서 빌린 돈입니다.","선으로 표현하거나 여러 자료층을 처리하거나 수동 입력할 때 오차가 발생한다":"선으로 나타내거나 여러 자료층을 겹쳐 처리하거나 손으로 입력할 때 오차가 생깁니다.","선형도시는 소리아 이 마타, 모형도시는 풀만, 공업도시는 가르니에가 제안했다":"소리아 이 마타는 선형도시, 풀만은 모형도시, 가르니에는 공업도시를 각각 내놓았어요.","설립 인가일로부터 30일 이내에 등기해야 한다":"조합은 설립 인가를 받은 날부터 30일 안에 등기를 마쳐야 합니다.","설치범위는 단지 밖 간선도로부터 경계선까지이다":"도로 간선시설은 단지 밖 간선도로에서 단지 경계선까지 놓아요.","성공적인 지역계획은 지속적 조정 전략과 자료 갱신 체계, 주민 여론의 주기적 파악이 필요하다":"지역계획이 성공하려면 계속 조정하는 전략, 자료를 갱신하는 체계, 주민 여론을 주기적으로 파악하는 일이 필요합니다.","성벽과 대규모 사원이 공간의 주된 구성요소였다":"중세 도시에서는 성벽과 큰 사원이 공간의 주된 구성요소였어요.","성장거점이론은 하향식 개발논리이며 생태중심개발·기본수요접근은 상향식이다":"성장거점이론은 위에서 아래로 가는 개발 논리이고, 생태중심개발과 기본수요접근은 아래에서 위로 가는 논리입니다.","성장률과 소득수준에 따라 번성지역·잠재적저개발지역·저개발지역 등으로 지역을 분류했다":"클라센은 성장률과 소득수준에 따라 번성지역, 잠재적저개발지역, 저개발지역 등으로 지역을 나눴어요.","성장을 통해 소득이 높아지면 자동으로 기본수요가 충족된다는 가정은 비판 대상이다":"성장해서 소득이 오르면 기본수요가 저절로 채워진다는 가정은 비판을 받습니다.","성장인자모형·중력모형·기회모형을 쓰며 회귀분석모형은 통행발생 단계에 쓰인다":"통행분포 단계에서는 성장인자모형, 중력모형, 기회모형을 쓰고 회귀분석모형은 통행발생 단계에 씁니다.","세수 증대는 성장관리정책의 목적이 아니다":"세수를 늘리는 것은 성장관리정책이 내세우는 목적이 아닙니다.","세 존이 유기적으로 연계되어야 테크노폴리스가 기능한다":"세 구역이 서로 유기적으로 이어져야 테크노폴리스가 제 기능을 합니다.","소가구는 10~24획지 내외로, 대가구는 루프형·3지 교차도로로 구성한다":"단독주택용지의 작은 가구는 10~24획지쯤으로, 큰 가구는 고리형이나 세 갈래 교차도로로 구성해요.","소규모 서비스 중심지·농촌 개발은 투자 효율성 면에서 집중 억제 수단이 된다":"소규모 서비스 중심지와 농촌을 개발하면 투자 효율 면에서 집중을 억제하는 수단이 됩니다.","소득·고용 중 어느 지표를 쓸지, 지역 범위를 어디까지 할지가 문제다":"소득과 고용 가운데 어떤 지표를 쓸지, 지역 범위를 어디까지 잡을지가 문제로 남아요.","소매 흡입력을 구하는 모형으로 소득격차 측정법이 아니다":"허프모형은 소매점이 손님을 끄는 힘을 구하는 모형으로 소득격차를 재는 방법이 아닙니다.","소방용수시설과 철도는 이러한 비용부담 대상 정비기반시설에 포함되지 않는다":"소방용수시설과 철도는 이 비용부담 대상 정비기반시설에 들어가지 않아요.","소비자 선호도 변화, 경쟁구조 변화, 분양가 책정 적정성":"시장위험은 소비자 선호가 바뀌거나 경쟁 구조가 달라지거나 분양가가 적정하지 않을 때 생깁니다.","소생활권에는 주민센터·초등학교, 대생활권에는 소방서가 배치된다":"소생활권에는 주민센터와 초등학교, 대생활권에는 소방서 같은 시설을 둡니다.","소수의 대안 위주로 자본집약적이며 교통수요가 고정됐다고 가정한다":"장기교통계획은 적은 수의 대안 위주이고 자본이 많이 들며 교통수요가 고정되어 있다고 가정합니다.","소유·관리 형태와 구조에 따라 구분된다":"공동주택은 소유와 관리 형태, 건물 구조를 기준으로 나눕니다.","손실보상 및 토지 등의 수용은 관리처분계획 내용이 아니다":"손실보상과 수용은 관리처분계획에 넣는 내용이 아닙니다.","쇠퇴지역의 경제·사회·물리적 활성화가 목적이며 기존 재개발처럼 전면 철거하는 것은 아니다":"쇠퇴한 곳의 경제·사회·물리 환경을 되살리는 것이 목표이고, 한꺼번에 허무는 재개발과 다릅니다.","수도권 과밀억제권역에서 이전하려는 자, 아파트형 공장 설립자는 산업시설용지를 우선 선정받는다":"과밀억제권역에서 옮겨 오려는 사람과 아파트형 공장을 세우려는 사람은 산업시설용지를 먼저 받아요.","수도권발전계획·광역권개발계획·개발촉진지구개발계획이며 부문별계획은 별개 범주다":"지역계획은 수도권발전계획, 광역권개발계획, 개발촉진지구개발계획이며 부문별계획은 따로 나뉜 범주예요.","수도권에는 개발촉진지구를 지정할 수 없으며 지정기간이 지나면 자동으로 해제된다":"수도권에서는 개발촉진지구를 지정하지 않고, 정해진 기간이 끝나면 지정이 저절로 풀립니다.","수도권은 과밀억제권역·성장관리권역·자연보전권역으로 구분되며 개발유도권역은 없다":"수도권은 세 권역으로 구분하며, 개발을 유도하는 권역은 따로 두지 않았어요.","수도권은 서울·인천·경기를 포함하며 과밀억제·성장관리·자연보전권역으로 나뉜다":"수도권에는 서울, 인천, 경기가 들어가고 세 권역으로 갈립니다.","수도권정비위원회 심의를 거쳐 연수시설 신축이 가능하다":"성장관리권역에서는 수도권정비위원회 심의를 거치면 연수시설을 새로 지을 수 있습니다.","수림대·구릉지·하천변 등 자연경관이 양호한 지역은 경관상세계획 수립 대상이다":"숲띠, 구릉지, 하천변처럼 자연경관이 좋은 곳은 경관상세계획 수립 대상이에요.","수용 당시 소유자로부터 권리를 승계받은 자도 환매권자가 될 수 있다":"수용 당시 소유자의 권리를 이어받은 사람도 환매권자가 될 수 있습니다.","수자원 보호, 지역 간 산업 연관관계 도모, 인구의 적정 배분을 위해 필요하다":"수자원을 보호하고 지역 간 산업 연관을 높이며 인구를 알맞게 배분하려고 지역계획이 필요합니다.","수평각 대신 세 변의 길이를 관측해 삼각점 위치를 구한다":"삼변측량은 각을 재지 않고 삼각형 세 변의 길이를 재어 삼각점의 위치를 구합니다.","순위-규모 법칙, 싸이몬 비례효과법칙, 엔트로피 극대화모형":"도시 규모 분포를 설명하는 모형에는 순위-규모 법칙, 싸이몬 비례효과법칙, 엔트로피 극대화모형이 있습니다.","순차 개발의 후순위 지역, 우수 설계안이 필요한 곳도 특별계획구역 지정 대상이다":"순서대로 개발하는 땅의 뒷순위 지역이나 뛰어난 설계안이 필요한 곳도 지정 대상입니다.","순현재가치(NPV)·내부수익률(IRR)·수익성지수(PI)":"사업성 평가지표로는 순현재가치(NPV), 내부수익률(IRR), 수익성지수(PI)를 씁니다.","슈퍼블록을 구성하고 보차분리를 원칙으로 하며 도로를 기능별 4종으로 나눴다":"래드번은 슈퍼블록을 구성하고 사람과 차를 분리하는 것을 원칙으로 하며 도로를 기능별 네 종류로 나눴어요.","슈퍼블록 활용은 뉴어바니즘의 특징이 아니며 다양한 주택·보행성·연결성이 핵심 원칙이다":"슈퍼블록 활용은 뉴어바니즘의 특징이 아니고, 다양한 주택과 걷기 좋음과 연결성이 핵심 원칙입니다.","스와송이 아니라 언윈과 파커가 계획했다":"레치워스를 계획한 사람은 스와송이 아니라 언윈과 파커입니다.","스카이라인에 율동감을 주고 고층화를 억제한 중·고밀도 군집형태를 추구한다":"스카이라인에 리듬감을 주고 고층화를 억제한 중·고밀도의 군집 형태가 바람직합니다.","스키장업에는 숙박시설을 설치할 수 있고 골프장업 숙박시설은 5층을 넘을 수 없다":"스키장업은 숙박시설을 둘 수 있고, 골프장업의 숙박시설은 5층 이하여야 합니다.","승인 시 중앙도시계획위원회의 심의를 거치며 5년 단위로 국토교통부장관의 승인을 받는다":"중앙도시계획위원회 심의를 거쳐 5년마다 국토교통부장관의 승인을 받습니다.","승인 신청 시 사업계획승인신청서·사업계획서·배치도를 제출하며 대지조성공사설계도서는 제외된다":"승인을 신청할 때 사업계획승인신청서, 사업계획서, 배치도를 내고 대지조성공사설계도서는 뺍니다.","시가화조정구역 지정의 실효고시는 실효일자·사유와 내용을 관보에 게재한다":"시가화조정구역 지정이 효력을 잃으면 실효일자, 사유, 내용을 관보에 올립니다.","시각회랑에 의한 방법도 경관분석기법에 포함된다":"시각회랑을 이용하는 방법도 경관분석기법에 들어갑니다.","시계열분석·인과분석법·중력모형은 정량적 예측모형이며 델파이법은 정성적 기법이다":"시계열분석, 인과분석법, 중력모형은 숫자로 예측하는 정량적 모형이고, 델파이법은 전문가 의견에 의존하는 정성적 기법입니다.","시·군 교통의 집산기능을 하며 근린주거구역 외곽을 형성한다":"보조간선도로는 교통을 모으고 나누는 집산 기능을 하며 근린주거구역의 바깥 경계를 이룹니다.","시·군 상호간 대량 통과교통을 처리하며 시·군의 골격을 이룬다":"주간선도로는 시·군 사이의 많은 통과교통을 처리해 시·군의 뼈대를 이룹니다.","시나리오법·델파이법·판단결정모델은 정성적 예측모형이며 인과분석법은 정량적 기법이다":"시나리오법, 델파이법, 판단결정모델은 질적 예측모형이고 인과분석법은 양적 기법입니다.","시·도지사나 대도시 시장이 지정·고시하면 국토교통부장관에게 통보한다":"지정권자가 구역을 정하고 고시하면 그 사실을 국토교통부장관에게도 알려야 합니다.","시·도지사는 개발제한구역 내 집단거주 취락을 취락지구로 지정할 수 있다":"개발제한구역 안에 사람이 모여 사는 마을은 시·도지사가 취락지구로 지정할 수 있습니다.","시·도지사는 지정 신청을 받으면 관계 행정기관장 심의가 아닌 다른 절차로 지정한다":"시·도지사가 지정하는 절차는 관계 행정기관장 심의로 하는 방식과 다릅니다.","시민(citizen), 활동(activity), 토지와 시설(land & facility)":"도시는 사람인 시민, 그들이 하는 활동, 그것을 담는 토지와 시설이 모여 이루어집니다.","시민 공동생활을 지원하는 기반시설로 도시관리계획으로 결정한다":"도시계획시설은 시민의 공동생활을 돕는 기반시설이며 도시관리계획으로 결정합니다.","시설간 유기적 관련성이 높고 공공공간을 공동 이용해 용지를 절약한다":"집중형은 시설끼리 유기적 관련성이 높고 공공공간을 함께 써서 용지를 아낄 수 있어요.","시설 설치로 수용될 토지의 세목을 첨부하는 것은 이 계획에 포함되는 사항이 아니다":"수용할 땅의 세목을 붙이는 일은 개발제한구역관리계획이 다루는 사항이 아닙니다.","시장·교통·행정 포섭원리로 중심지 계층을 설명한다":"시장, 교통, 행정의 세 포섭원리로 중심지가 계층을 이루는 모습을 설명합니다.","시장·군수·구청장은 시·도지사에게 도시첨단산업단지 지정을 신청할 수 있다":"도시첨단산업단지는 시장, 군수, 구청장이 시·도지사에게 지정해 달라고 요청하는 형태로 시작합니다.","시장중심의 수나 생산 공장의 규모는 시장권 크기를 결정하는 요인이 아니다":"시장중심이 몇 개인지, 공장이 얼마나 큰지는 시장권의 크기를 가르는 변수가 아닙니다.","시행자가 실시계획 인가를 기간 내 신청하지 않거나 부도가 나면 지정권자가 시행자를 변경할 수 있다":"인가를 제때 신청하지 않거나 시행자가 부도나면, 지정권자가 사업을 맡을 사람을 바꿀 수 있어요.","신도시는 저개발지역 발전 거점화, 고용·소득 증대, 신수도 조성을 목적으로 한다":"신도시는 저개발지역을 발전 거점으로 삼고 고용과 소득을 늘리며 새 수도를 만들려는 목적이 있어요.","신도시를 다수 건설해 교외화를 촉진하는 것은 지속가능한 방향이 아니다":"신도시를 여러 개 지어 교외로 퍼지게 하면 지속가능성에서 멀어집니다.","신체적 접촉·사회적 면식·단위근린주구 세 가지로 나뉜 개념은 아니다":"신체적 접촉, 사회적 면식, 단위근린주구로 가르는 것은 근린주구의 구분이 아닙니다.","신축 건물 부담금제도와 기업체 신증축 사전허가제도 집중억제 정책이다":"새 건물에 부담금을 매기고 기업의 신증축을 사전허가제로 하는 것도 집중억제 정책입니다.","신축·증축·개축·이전을 뜻하며 대수선은 건축과 별도로 구분되는 개념이다":"건축은 신축, 증축, 개축, 이전을 뜻하며 대수선은 건축과 따로 구분되는 개념입니다.","신휴머니즘 철학에 기초해 분권화된 사회적 의사결정 참여를 늘리려 한다":"신휴머니즘 철학을 바탕으로 분권화된 사회적 의사결정에 참여할 기회를 넓히려 합니다.","실제 결과를 기준으로 규제하는 성과규제지역제는 유클리드 지역제가 아니다":"결과를 보고 규제하는 성과규제지역제는 용도를 미리 정해 두는 유클리드 방식과 다릅니다.","아산만-대전-청주, 군산-익산-전주, 목포-광주-광양만이며 창원-마산-진해는 포함되지 않는다":"신산업지대는 세 갈래 축으로 구상됐으며 창원-마산-진해 축은 그 안에 들지 않아요.","아파트처럼 토지와 완전히 분리된 공동주택이다":"비접지형은 아파트처럼 땅과 완전히 떨어진 공동주택을 말합니다.","안전성·편의성·경제성이며 형평성은 아니다":"토지이용계획이 세우는 목표는 안전성, 편의성, 경제성이며 형평성은 포함되지 않습니다.","안전점검은 1년에 1회 이상 실시하며 관리비용은 연 2회로 나눠 납부한다":"안전점검은 1년에 한 번 이상 하고, 관리비용은 연 2회로 나눠 냅니다.","안정적인 도시에 지수성장모형을 쓰면 인구를 과도하게 예측할 수 있다":"안정된 도시에 이 모형을 쓰면 인구를 실제보다 훨씬 크게 예측할 수 있어요.","압축도시 개발의 핵심 조성 대상이 될 수 있다":"도심부는 압축도시 개발에서 핵심으로 만들 수 있는 대상이에요.","압축도시의 핵심 개념은 직주분리가 아니라 직주근접이다":"압축도시는 직장과 집을 떼어 놓는 직주분리가 아니라 가깝게 두는 직주근접을 중심으로 합니다.","압출·흡인요인 간 관계로 인구변화를 설명하는 것도 집단생잔법과 다르다":"밀어내는 요인과 끌어당기는 요인의 관계로 인구 변화를 설명하는 것도 집단생잔법과 다릅니다.","어린이공원의 공원시설 부지면적은 60% 이하, 근린공원은 40% 이하다":"공원시설을 둘 수 있는 부지는 어린이공원이 60% 이하, 근린공원이 40% 이하예요.","어린이놀이터, 일반목욕장, 노인정 설치용지이나 공동주택용지는 아니다":"공공시설용지는 어린이놀이터, 일반목욕장, 노인정을 설치할 땅이며 공동주택용지는 아닙니다.","어반 스프롤 방지, 효율적 도시형태 구축, 경제적 효율성 제고":"도시가 무분별하게 퍼지는 어반 스프롤을 막고 효율적 도시형태를 만들며 경제적 효율성을 높이려는 정책입니다.","업무시설·복합시설이 주용도인 건축물로 연면적 25,000㎡ 이상이면 인구집중유발시설이다":"업무시설이나 복합시설이 주용도이고 연면적이 25,000㎡ 이상인 건축물이 인구집중유발시설이에요.","에너지 절약, 시설 집적화, 고밀도 개발을 통한 자연환경 보존을 추구한다":"에너지를 아끼고 시설을 모으고 고밀도로 개발해 자연환경을 지키는 방향입니다.","여러 개의 마스터플랜이 아니라 하나의 통합된 계획으로 복합 개발을 수행한다":"복합개발은 마스터플랜 여러 개가 아니라 하나로 묶은 통합계획으로 수행합니다.","여름철 과다한 일조를 피하려고 인동간격을 좁히는 것은 아니다":"여름철에 햇빛이 지나치게 드는 것을 피하려고 인동간격을 좁히는 것은 아닙니다.","역사적 건축물 보존, 저소득층 주택 건설, 녹지·생태지역 보호":"역사적 건축물을 보존하고 저소득층 주택을 짓고 녹지와 생태지역을 보호하려는 목적입니다.","역사환경을 문화 창조·활성화 자원으로 활용하며 과거 보존에만 치우치지 않고 현재와 조화를 이뤄야 한다":"역사환경을 문화를 만들고 되살리는 자원으로 쓰되, 과거 보존에만 치우치지 않고 현재와 어울려야 합니다.","역세권개발사업과 관광지조성사업은 이 의무설치 대상에 포함되지 않는다":"역세권개발사업과 관광지조성사업은 의무설치 대상이 아닙니다.","연결성·인접성·면적정의는 위상관계 설정 요소이며 단순성은 아니다":"위상관계를 정할 때 연결성, 인접성, 면적정의를 쓰고 단순성은 쓰지 않습니다.","연령계층별 생존모형은 요소모형이며 선형·지수모형은 비요소모형이다":"연령계층별 생존모형은 요소모형이고 선형모형과 지수모형은 요소를 나누지 않는 비요소모형입니다.","연립주택·아파트·다세대주택·기숙사":"공동주택에는 연립주택, 아파트, 다세대주택, 기숙사가 있습니다.","연면적을 대지면적으로 나눈 값이다":"용적률은 건물의 연면적을 대지면적으로 나눈 값이에요.","열수송관 분기점부터 단지 내 각 기계실 입구까지를 범위로 한다":"지역난방은 열수송관 분기점에서 단지 안 각 기계실 입구까지가 설치범위입니다.","영월·서산·점촌생활권이 있고 영주생활권은 없다":"농촌도시 생활권은 영월, 서산, 점촌이 해당하며 영주는 포함되지 않아요.","예산 마련, 인원·자재 배분, 제도·기구의 신설·변경 세 가지로 이루어진다":"집행은 예산을 마련하고, 사람과 자재를 나누고, 제도와 기구를 새로 만들거나 바꾸는 일입니다.","예정지구 면적의 10% 이내 확대·축소, 사업비 10% 이내 증감":"예정지구 면적의 10% 이내를 늘리거나 줄이는 것과 사업비 10% 이내의 증감은 경미한 변경입니다.","예정지구 지정 후 2년 이내 택지개발계획 승인을 신청하지 않으면 효력을 잃는다":"예정지구로 지정되고 2년 안에 택지개발계획 승인을 신청하지 않으면 지정이 효력을 잃습니다.","오스만의 파리대개조계획은 집중억제 정책이 아니다":"오스만이 파리를 크게 고친 계획은 인구와 기능이 파리에 몰리는 것을 막으려는 정책에 들지 않습니다.","오픈스페이스는 차경(借景) 기회를 제공하며 평탄하고 접근성 좋은 곳만 우선 확보하는 것은 아니다":"오픈스페이스는 멀리 있는 경치를 빌려 오는 차경의 기회를 주며, 평탄하고 접근 좋은 곳만 먼저 확보하는 것은 아닙니다.","온도 변화, 테이프 눈금 잘못, 테이프 처짐":"정오차는 온도, 눈금, 처짐처럼 원인을 알 수 있어서 보정으로 줄일 수 있는 오차예요.","완충녹지는 공해 방지, 경관녹지는 자연환경 보전·개선을 위해 설치한다":"완충녹지는 공해를 막으려고, 경관녹지는 자연환경을 지키고 개선하려고 설치합니다.","완충녹지는 공해·재해·사고 방지, 경관녹지는 자연환경 보전·복원, 연결녹지는 공원·녹지를 유기적으로 잇는다":"완충녹지는 공해, 재해, 사고를 막고 경관녹지는 자연환경을 지키고 복원하며 연결녹지는 공원과 녹지를 이어 줍니다.","왜곡된 지역산업구조는 입지여건 개선, 산업구조 고도화, 부가가치의 역내환류로 개선한다":"왜곡된 지역산업구조는 입지 여건을 개선하고 산업구조를 고도화하며 부가가치가 지역 안으로 되돌아오게 해 바로잡습니다.","외곽으로 갈수록 1인당 주거서비스 소비량은 늘고 도심으로 갈수록 인구밀도는 높아진다":"도심에서 멀수록 주거에 쓰는 몫은 커지고 사람 수 밀도는 도심에서 가장 높습니다.","외관으로 판단하고 기능 분화가 현저하며 경제활동이 다양하다":"도시사회는 겉모습으로 판단하며 기능이 뚜렷이 나뉘고 경제활동이 다양해요.","외부시장을 갖는 수출형 산업이며 주변지역에 상품·서비스를 공급한다":"주축산업은 외부 시장에 팔아 돈을 벌며, 주변 지역에 상품과 서비스를 공급하는 수출형 산업이에요.","외부 원조에 의존한 균형발전이 아니라 주민의 자립과 참여를 중시한다":"외부 원조에 기대는 균형발전이 아니라 주민이 스스로 서고 참여하는 것을 중시해요.","외생변수가 아니라 격차의 결과다":"소득은 격차의 원인이 아니라 격차가 드러난 결과 값이어서 외생변수가 아닙니다.","요새·시장·법정·결사체·정치적 자율성을 갖춘 곳":"베버가 말한 완전한 도시공동체는 요새, 시장, 법정, 결사체, 정치적 자율성을 갖춘 곳입니다.","요인분석·군집분석·가중지표방식":"동질지역은 요인분석, 군집분석, 가중지표방식으로 가려냅니다.","용도구역이지 공원녹지 자체로 분류되지 않는다":"도시자연공원구역은 용도구역이고 공원녹지 자체로 분류하지 않습니다.","용도 규제, 건폐율 규제, 건축물 높이 제한":"용도를 규제하고 건폐율을 규제하고 건축물 높이를 제한하는 것이 강제적(직접적) 수단입니다.","용도를 사전에 확정적으로 지정하며 개발 억제에 관심을 둔다":"용도를 미리 확정해 지정하며 개발을 억제하는 데 관심을 둡니다.","용도지역·지구단위계획구역 지정, 기반시설 설치":"용도지역과 지구단위계획구역을 지정하고 기반시설을 설치하는 일이 도시관리계획에 들어요.","용도지역 지정·변경, 기반시설 설치·정비, 도시개발·정비사업":"도시·군관리계획에는 용도지역 지정과 변경, 기반시설 설치와 정비, 도시개발과 정비사업이 들어갑니다.","용적률 최대한도는 80% 이하다":"보전관리지역의 용적률 최대한도는 80% 이하입니다.","우리나라 도시설계는 1980년대 건축법에 조항을 법제화하며 도입되었고 초기 관심은 간선가로 미관 개선이었다":"우리나라 도시설계는 1980년대 건축법에 조항을 넣으며 시작됐고 처음에는 간선가로 미관 개선에 관심이 있었어요.","우리나라 지질이 안정적인 사암이고 암반 면적이 넓다는 점은 지하공간 개발 배경이 아니다":"지질이 단단한 사암이고 암반이 넓다는 점은 지하를 개발하게 된 배경이 아닙니다.","우수시공사 협약, CM사 선정, 완공보험·지체보상금으로 관리한다":"공사 완공이 늦어질 위험은 우수 시공사와 협약하고 CM사를 뽑고 완공보험과 지체보상금으로 관리해요.","우주부문·제어부문·사용자부문으로 구성된다":"GPS는 우주부문, 제어부문, 사용자부문의 세 부문으로 이루어집니다.","운동시설, 우체국, 일반목욕장이며 공용시장은 아니다":"주거생활 편익시설은 운동시설, 우체국, 일반목욕장이고 공용시장은 해당하지 않아요.","운동장·공용청사·도로의 지하에는 노외주차장을 설치할 수 있으나 공항은 아니다":"운동장, 공용청사, 도로 지하에는 노외주차장을 둘 수 있고 공항은 해당하지 않습니다.","원단위법 등으로 이러한 정량적 변수를 활용해 수요를 추정한다":"수요를 추정할 때는 원단위법 등에 이 정량 변수들을 대입해요.","원리금 상환 부담이 있고 과도한 차입은 부도 확률을 높인다":"빌린 돈은 원금과 이자를 갚아야 하고, 너무 많이 빌리면 부도 가능성이 커집니다.","원인시설에 접한 부분부터 최소 10m 이상이다":"완충녹지의 폭은 원인이 되는 시설에 맞닿은 부분부터 최소 10m 이상이어야 해요.","원자료의 오차도 자료기반에 포함되며, 연속 변화는 등치선법 등으로 표현한다":"원래 자료의 오차도 자료기반에 그대로 들어가고, 연속으로 변하는 값은 등치선법 등으로 표현해요.","위도 남·북 80°까지 포함하며 적도를 횡축, 자오선을 종축으로 한다":"UTM좌표계는 위도 남북 80°까지 포함하고 적도를 횡축, 자오선을 종축으로 삼습니다.","위원장 1명과 25명 이내의 위원으로 구성한다":"실무위원회는 위원장 1명과 25명 이내의 위원으로 구성합니다.","위원장 1인, 부위원장 2인과 34인 이내의 위원으로 구성하며 위원장이 국토교통부장관은 아니다":"위원회는 위원장과 부위원장 둘, 위원 34인 이내로 꾸리며 위원장은 국토교통부장관이 아닙니다.","위원장이 국토교통부장관을 맡는 것은 아니다":"위원장 자리에 국토교통부장관이 앉는 것은 아닙니다.","유도적 제도가 아니라 규제적 성격이 강하다":"특별허가는 유도하기보다 규제하는 성격이 강합니다.","유원지, 사회복지시설, 청소년수련시설이며 노유자시설은 아니다":"기반시설에는 유원지, 사회복지시설, 청소년수련시설이 있고 노유자시설은 해당하지 않아요.","육교·횡단보도 인근, 유치원 출입구 20m 이내, 종단구배 10% 초과 도로에는 둘 수 없다":"육교와 횡단보도 가까이, 유치원 출입구 20m 안, 종단구배 10%를 넘는 도로에는 출입구를 낼 수 없어요.","이동거리를 줄여 자동차에 의한 환경파괴를 막으려 한다":"이동거리를 줄여서 자동차가 일으키는 환경 파괴를 막으려 해요.","이동평균법·지수평활법·박스젠킨스법이 있다":"시계열분석에는 이동평균법, 지수평활법, 박스젠킨스법이 있어요.","이 모형은 자료 수집이 쉽고 신뢰도가 낮은 것이 아니라 오히려 자료 수집이 어렵고 신뢰도가 높다":"이 모형은 자료를 모으기 쉽고 믿을 수 없다는 말과 반대로, 자료 모으기는 어려워도 신뢰도가 높습니다.","이미 부담금이 부과된 시설을 용도변경하는 경우에도 부담금을 부과하지 않는다":"이미 부담금을 낸 시설의 용도를 바꿀 때는 다시 부과하지 않습니다.","이 세 요인은 토지이용계획 수립 시 종합적으로 고려된다":"이 세 요인은 토지이용계획을 세울 때 함께 종합해서 따집니다.","이 요소들은 사람들이 도시를 인지하는 물리적 구조 단위다":"이 요소들은 사람들이 도시를 머릿속에 그릴 때 쓰는 물리적 구조 단위입니다.","이용목적에 맞지 않는 행위를 규제하고 맞는 행위는 유도한다":"이용 목적에 어긋나는 행위는 막고 알맞은 행위는 장려하는 방식으로 작동해요.","이용인구에 의한 방법, 원단위에 의한 방법, 상업기능에 의한 방법":"상업용지 면적은 이용인구, 원단위, 상업기능에 따른 방법으로 산정해요.","이윤 극대화가 아니라 도시의 발전과 성장이다":"도시마케팅이 노리는 것은 이윤을 최대로 키우는 일이 아니라 도시가 발전하고 커지는 것입니다.","이 이론은 수입부문을 완전히 무시하며 기반·비기반 산업을 나누기도 쉽지 않다":"수입부문을 완전히 무시하고, 기반산업과 비기반산업을 나누기도 쉽지 않습니다.","이전촉진권역·접경관리권역·개발유도권역이라는 구분은 없다":"이전촉진권역, 접경관리권역, 개발유도권역이라는 구분은 존재하지 않습니다.","인가 고시 후에는 정비사업 종류·명칭, 시행구역 면적, 인가일을 분양신청자에게 통지한다":"인가 고시 뒤 분양신청자에게 사업 종류와 명칭, 구역 면적, 인가일을 알립니다.","인가는 제3자의 행위를 보충해 법률상 효력을 완성시키는 것이며 승인은 국가·지자체의 동의·승낙이다":"인가는 제3자가 한 행위를 보충해 법률상 효력을 완성시키는 것이고, 승인은 국가나 지자체가 동의하고 승낙하는 것이에요.","인구가 정률로 변하는 신도시처럼 급팽창하는 곳에 적합하다":"인구가 일정한 비율로 변하는 신도시처럼 급하게 커지는 곳에 지수성장모형이 맞습니다.","인구분포, 역사적 전통, 자연적 요소로 설정하며 교육수준은 기준이 아니다":"광역도시권은 인구가 분포한 모양, 역사적 전통, 자연 조건을 보고 정하며 교육수준은 기준에서 빠집니다.","인구·산업발전 상황을 고려해 도시관리계획으로 시가화 유보기간을 정한다":"인구와 산업의 발전 상황을 보아 도시관리계획으로 시가화 유보기간을 정해요.","인구·산업 배치, 환경보전, 권역별 정비 사항이 포함된다":"수도권정비계획에는 인구와 산업 배치, 환경보전, 권역별 정비 사항이 들어갑니다.","인구의 증가·이동, 환경적 요인, 기술적 진보":"도시가 생기려면 인구가 늘고 이동하며, 환경적 요인과 기술의 진보가 뒤따라야 합니다.","인구이동을 흡인요인·배출(밀어내는)요인·중간개입장애요인으로 설명한다":"인구이동은 끌어당기는 흡인요인, 밀어내는 배출요인, 중간에 가로막는 장애요인으로 설명합니다.","인구이동 통제가 토지이용 규제보다 더 유효하고 적법한 수단은 아니다":"인구이동을 막는 것이 땅 쓰임을 규제하는 것보다 더 효과적이고 합법적이라고 할 수는 없어요.","인근 300m 이내로 새 부지를 마련해 옮기는 것은 허용되는 용도변경이 아니다":"300m 안의 다른 부지로 주차장을 옮겨 짓는 것은 용도변경으로 허용되지 않습니다.","인프라·에너지를 효율적으로 쓰고 교외 확산을 막지만 지가 안정을 보장하지는 않는다":"컴팩트시티는 인프라와 에너지를 효율적으로 쓰고 교외로 퍼지는 것을 막지만, 땅값이 안정된다고 보장하지는 않아요.","일반 도시계획보다 구체화된 특수계획이며 소극적 계획이 아니다":"일반 도시계획에서 한 걸음 더 구체화한 특수 계획이고 소극적이지 않습니다.","일반산업단지는 시·도지사 또는 대통령령이 정하는 시장이, 농공단지는 시장·군수·구청장이 지정한다":"일반산업단지는 시·도지사 등이, 농공단지는 시장·군수·구청장이 지정하는 권한을 가집니다.","일반적인 단지 환경의 소음은 50~60dB 이하로 유지되어야 한다":"단지 환경의 일반적인 소음은 50~60dB 이하로 유지해야 해요.","일반 주차구획은 너비 2.3m·길이 5m 이상, 경형은 너비 2m·길이 3.5m 이상이다":"일반 한 칸은 너비 2.3m 길이 5m 이상이고, 경형은 이보다 작은 너비 2m 길이 3.5m 이상이에요.","일부 지역을 체계적이고 계획적으로 관리하는 입체적·적극적 계획이다":"일부 지역을 짜임새 있게 관리하는 적극적이고 입체적인 계획입니다.","일정 규모 이상의 공장, 대학, 중앙행정청사는 인구집중유발시설로 관리된다":"일정 규모를 넘는 공장, 대학, 중앙행정청사는 사람을 몰리게 하는 시설로 따로 관리합니다.","일조, 프라이버시, 조망을 고려해 결정하며 도로는 직접적 요소가 아니다":"인동간격은 일조, 프라이버시, 조망을 고려해 정하고 도로는 직접 영향을 주는 요소가 아닙니다.","입도, 교통패턴의 시간적 거리, 결절점의 공간적 관계":"동태적 도시구성의 요소는 입도, 교통패턴의 시간적 거리, 결절점의 공간적 관계예요.","입지계수(LQ)가 1보다 크면 해당 지역이 그 산업에 특화되어 있음을 뜻한다":"입지계수가 1보다 크면 그 지역이 해당 산업에 특화되어 있다고 읽습니다.","입지계수(LQ)는 지역과 전국의 노동생산성·소비수준·상품 동질성이 같다고 가정한다":"입지계수는 지역과 전국이 생산성과 소비수준, 상품의 질이 같다는 가정 위에서 쓰는 지표입니다.","입지계수법은 수출기반모형 중 수요모형에 해당한다":"입지계수법은 수출기반모형을 수요 쪽에서 응용한 방법입니다.","입찰지대가 가장 낮은 곳은 상업용이 아니라 농업용 토지로 이용된다":"입찰지대가 가장 낮은 땅은 상업용이 아니라 농업용으로 쓰입니다.","입찰지대가 높은 곳은 개발 밀도도 높으며 중심지에서 가장 높고 외곽으로 갈수록 낮아진다":"입찰지대가 높으면 그만큼 높은 밀도로 개발되며, 중심지가 가장 높고 바깥으로 갈수록 낮아집니다.","입찰지대는 동심원이론을 뒷받침하는 경제학적 토대가 된다":"입찰지대는 동심원이론을 경제학적으로 받쳐 주는 토대가 됩니다.","입체적 도시계획시설을 설치할 때는 미리 토지소유자 등과 협의한다":"입체적으로 시설을 설치하려면 토지소유자 등과 미리 협의를 거쳐야 해요.","자급자족형 성장산업은 기반산업이 아니다":"스스로 먹고사는 자급자족형 성장산업은 기반산업이 아닙니다.","자동차 출입구는 이면도로를 이용하고 교차로 가까이에는 배치하지 않는다":"주택단지의 차 출입구는 이면도로에 내고, 교차로와 가까운 곳은 피합니다.","자본시장 여건에 민감하고 지분(경영권) 축소가 불가피하다":"지분조달은 자본시장 상황에 좌우되고 경영권 지분이 줄어드는 일을 피할 수 없습니다.","자연공원·국립공원은 별도 법에 따른 공원으로 도시공원이 아니다":"자연공원과 국립공원은 다른 법으로 관리하므로 도시공원에서 제외됩니다.","자연·인공경관으로, 형태에 따라 점·선·면적으로, 범위에 따라 광역·도시·시가지·지구 경관으로 나뉜다":"경관은 자연·인공으로 가르고, 모양에 따라 점·선·면으로, 범위에 따라 광역에서 지구까지 나눕니다.","자연자원·입지조건·산업구조·주민의식의 지역간 차이가 지역문제를 낳는다":"자연자원, 입지조건, 산업구조, 주민의식이 지역마다 달라서 지역문제가 생깁니다.","자연조건 반영, 조화와 개성 부여, 커뮤니티 감각을 기본방향으로 한다":"경관계획의 기본방향은 자연조건을 반영하고, 조화 속에 개성을 주며, 커뮤니티 감각을 살리는 것입니다.","자연항을 주로 쓰고 아고라를 도시 입구와 신전 사이에 배치했다":"그리스 도시는 자연항을 주로 쓰고, 아고라를 도시 입구와 신전 사이에 두었습니다.","자연환경보전구역이라는 용도구역은 없다":"자연환경보전구역이라는 용도구역은 존재하지 않습니다.","자연환경 보전·복원, 생활환경 개선, 지역경제의 적정 기능배분":"국토이용 원칙은 자연환경을 보전하고 복원하며 생활환경을 개선하고 지역경제의 기능을 알맞게 나누는 것입니다.","자연환경·사회적 환경·교통환경을 다루며 분석자의 주관적 선호에 기반하지 않는다":"자연환경, 사회적 환경, 교통환경을 다루며 분석하는 사람의 주관적 취향에 따르지 않습니다.","자연환경 피해 최소화, 생태계 보존, 자연에너지 활용이며 불투수포장 확대는 아니다":"자연환경 피해를 줄이고 생태계를 보존하며 자연에너지를 쓰는 것이 목표이고, 물이 못 스며드는 포장을 늘리는 것은 아닙니다.","자원의 보호·개발·이용·관리, 환경보전, 관광지 조성·정비 사항을 담는다":"권역별관광개발계획은 자원 보호와 개발, 이용, 관리, 환경보전, 관광지 조성과 정비 사항을 담습니다.","자원의 집중투자 효율, 지역간 균형성장, 낙후지역 개발을 기대한다":"거점에 자원을 모아 투자하면 효율이 높고 지역 간 균형과 낙후지역 개발 효과를 기대합니다.","자원 조사·평가, 전망·대책 수립, 경관·미관지구 관리 사항이 들어간다":"경관계획에는 자원 조사와 평가, 전망과 대책 수립, 경관지구와 미관지구 관리가 들어갑니다.","자유무역을 억제하고 비교우위 원칙이나 다국적기업의 이념을 제한한다":"도농접근법은 자유무역을 억제하고 비교우위나 다국적기업의 논리를 제한하자는 입장이에요.","자유방임 전략은 집중효과를 초래하고 거점개발·지역대도시개발은 분산효과를 노린다":"자유방임은 사람과 기능이 한곳에 몰리게 하고, 거점개발이나 지역대도시개발은 널리 퍼지게 하려는 전략입니다.","자치적 도시정부의 구성 자체":"자치적인 도시정부를 만드는 것 자체는 도시화가 일어나기 위한 필요조건이 아닙니다.","작물 유형을 결정하는 요소가 아니다":"경작지가 얼마나 넓은지는 어떤 작물을 심을지 정하는 요소가 아닙니다.","작은 규모가 아니라 어느 정도 규모가 있는 주거형식에 적합하다":"작은 규모가 아니라 어느 정도 규모를 갖춘 주거형식에 알맞아요.","재개발사업 비용은 원칙적으로 시행자가 부담하며 시·군·구가 일부를 부담할 수 있다":"재개발 비용은 원칙적으로 시행자가 내고 시·군·구가 일부를 낼 수 있어요.","재개발은 농지를 택지로 전용하는 신개발과 달리 절차가 간단하지 않다":"신개발은 농지를 택지로 돌리는 일이어서 절차가 단순하지만, 재개발은 권리관계 때문에 절차가 복잡합니다.","재원은 과징금 징수금, 일반회계 전입금, 정부 보조금이며 자동차세의 20%는 아니다":"주차장특별회계는 과징금, 일반회계에서 오는 돈, 정부 보조금으로 채우며 자동차세의 20%를 쓰지는 않아요.","재원조달·보상계획이 포함되며 수립·송부 후 공고 기한은 7일이 아니다":"단계별 집행계획에는 재원조달과 보상계획이 들어가며 수립해서 보낸 뒤 공고 기한은 7일이 아닙니다.","재활체육시설은 법상 공공체육시설 분류에 포함되지 않는다":"재활체육시설은 법에서 공공체육시설로 분류하지 않습니다.","저당제도보다 대출채권 유동화가 쉽고 물상대위권 행사가 불필요하다":"담보신탁은 대출채권을 증권화하기 쉽고 물상대위권을 따로 행사할 필요가 없어요.","저에너지 소비, 저이동 유발, 저오염 배출을 추구하며 저밀도가 아닌 고밀도 건축을 지향한다":"에너지 소비와 이동 유발과 오염 배출을 줄이려 하고 저밀도가 아니라 고밀도 건축을 지향합니다.","저에너지·저이동·저오염 구조를 지향하며 토지는 복합이용을 추구한다":"에너지와 이동과 오염이 모두 적은 구조를 지향하고 토지는 복합적으로 씁니다.","적응·증·감환지처분은 협의의 환지처분이며 입체환지처분은 광의에 속한다":"적응, 증, 감환지처분이 좁은 뜻의 환지처분이고 입체환지처분은 넓은 뜻에 속합니다.","전국 수요수준이 동일하다고 가정하는 모순이 있고 중간재 특성은 고려하지 못한다":"전국의 수요 수준이 같다고 가정하는 모순이 있고, 중간재의 특성은 반영하지 못해요.","전국토 균형발전을 위한 지침 제시적 종합계획으로 중앙정부가 주체가 된다":"국토계획은 나라 전체의 균형 발전을 위한 지침을 주는 종합계획이고 중앙정부가 주체입니다.","전 국토를 대상으로 균형 발전과 삶의 질 개선을 추구하는 공간계획이다":"전국을 대상으로 지역 간 균형 발전과 삶의 질 개선을 노리는 공간 계획이에요.","전문가 집단에게 반복 설문해 의견을 수렴하는 기법이며 서면방식이 회의보다 낫다":"델파이법은 전문가 집단에 설문을 되풀이해 의견을 모으는 기법이고, 서면 방식이 회의보다 낫습니다.","전문체육시설, 생활체육시설, 직장체육시설은 공공체육시설이다":"전문, 생활, 직장 체육시설이 공공체육시설로 분류됩니다.","전신전화, 도매시장권, 인구이동·통근 자료는 결절지역 분석에 쓰이며 산업별 구성비는 동질지역 분석 자료다":"결절지역은 통신망, 도매시장권, 통근처럼 오가는 흐름으로 보고, 산업별 구성비는 동질지역 분석에 씁니다.","전원도시 규모를 3만 명 정도로 보았으며 공업지역을 단지 중심이 아니라 주변부에 배치했다":"하워드는 전원도시 규모를 3만 명 정도로 잡았고 공업지역은 단지 한가운데가 아닌 바깥쪽에 배치했어요.","전원도시들은 서로 독립적이지 않고 연계되며, 대표 사례는 영국 레치워스다":"전원도시들은 서로 떨어져 있지 않고 이어지며, 대표 사례는 영국의 레치워스입니다.","전체 개발지에 밀도·건폐율 규정을 적용하며 주택과 외부공간 배치가 자유롭다":"개발지 전체에 밀도와 건폐율 규정을 적용하므로 주택과 바깥 공간을 자유롭게 놓을 수 있습니다.","전통 건조물이나 시대적 건축특성이 있는 건물군 주변 지역도 대상이다":"전통 건조물이 있거나 시대적 건축 특성을 가진 건물군 주변도 대상입니다.","전통적 공업단지, 업무단지, 과학·첨단산업단지는 기능별 공업단지 유형이다":"공업단지는 기능에 따라 전통적 단지, 업무단지, 과학·첨단산업단지로 나눌 수 있어요.","전파·광파 거리측량기기 발달로 장거리를 정밀하게 측량할 수 있게 되었다":"전파나 광파로 거리를 재는 기기가 좋아지면서 먼 거리도 정밀하게 잴 수 있게 되었어요.","절벽 외에는 교차하지 않고 동일 등고선 위 모든 점은 같은 높이다":"절벽이 아니면 등고선은 만나지 않고, 같은 등고선 위의 점들은 높이가 같습니다.","절토를 최소화하고 저층 위주로 계획해야 한다":"구릉지는 땅을 깎는 절토를 최소로 하고 낮은 층 위주로 계획해야 합니다.","점이지대는 유동성이 심하고 도심 접근성이 좋아 비공식부문 종사자가 많이 산다":"점이지대는 사람 드나듦이 심하고 도심에 가까워 비공식부문에 종사하는 사람이 많이 삽니다.","점증적 스카이라인 형성은 정보화 사회 대응 계획요인으로는 부적절하며 LAN·교통정보시스템이 더 적절하다":"스카이라인이 조금씩 형성되게 하는 것은 정보화 사회 대응 요인으로 맞지 않고, LAN과 교통정보시스템이 더 알맞아요.","접촉이익, 승수효과, 예비능력 비축은 집적의 외부이익이며 규모의 경제 효과는 내부이익이다":"만남의 이익, 승수효과, 여유 능력은 집적의 외부이익이고, 규모의 경제는 내부이익이에요.","정기조사와 수시조사로 나뉘며, 정기조사의 주기는 5년이나 3년이 아니다":"국토조사는 정기와 수시로 나뉘며 정기조사의 주기는 5년도 3년도 아닌 다른 값이에요.","정방형 셀을 기본단위로 하는 것은 벡터 자료가 아니라 래스터 자료다":"정사각형 셀을 기본 단위로 삼는 자료는 벡터가 아니라 래스터입니다.","정보망으로 시간·장소 제한 없이 서비스를 이용하는 도시 개념이다":"U-City는 정보망 덕분에 시간과 장소에 제한 없이 서비스를 이용하는 도시입니다.","정비구역 내 국·공유지 비율이 일정 수준(1/3)인 것만으로는 직접 시행 사유가 아니다":"정비구역 안 국·공유지가 3분의 1이라는 점만으로는 직접 시행할 이유가 되지 않아요.","정비기반시설은 공공시설 중 기반 인프라에 해당하는 것으로 한정된다":"정비기반시설은 공공시설 가운데서도 기반 인프라에 해당하는 것으로 범위가 정해져 있어요.","정비기반시설은 양호하나 공동주택이 노후·불량한 지역에서 시행한다":"주택재건축사업은 정비기반시설은 좋은데 공동주택이 낡았거나 불량한 지역에서 시행해요.","정비기반시설이 극히 열악한 지역에서 시행한다":"주거환경개선사업은 정비기반시설이 극히 열악한 지역에서 시행합니다.","정비기반시설이 열악한 곳이 대상이다":"주택재개발사업은 정비기반시설이 열악한 곳이 대상입니다.","정책지향적·거시적·지침 제시적 성격을 가지며 구체적·실질적 계획은 아니다":"국토계획은 정책을 이끄는 큰 틀의 지침을 주는 성격이며, 구체적이고 실질적인 계획은 아닙니다.","정체성과 사회통합을 해체하려는 시도는 아니다":"도시민의 정체성과 사회통합을 허물려는 시도가 미래도시 패러다임은 아닙니다.","정확도가 높고 1인 측량이 가능하며 조작시간이 짧다":"광파거리측량기는 정확도가 높고 혼자서도 측량할 수 있으며 조작 시간이 짧습니다.","제1종·제2종으로 구분되며 도시관리계획으로 결정한다":"지구단위계획은 제1종과 제2종으로 구분하며 도시관리계획으로 결정해요.","제2종전용주거지역 50%, 전용공업지역 70%, 보전녹지지역 20% 이하다":"전용·주거·녹지 가운데 건폐율 상한이 제2종전용주거 50%, 전용공업 70%, 보전녹지 20%로 서로 다릅니다.","제3세계 도시화는 비공식부문이 확대되며 공식부문이 확대되는 것은 아니다":"제3세계에서는 도시화가 진행될수록 비공식부문이 커지고 공식부문이 커지는 것은 아닙니다.","제4차 기본목표는 균형국토·개방국토·녹색국토이며 웰빙국토는 아니다":"제4차 계획의 기본목표는 균형국토, 개방국토, 녹색국토이고 웰빙국토는 없어요.","제도적 지속성과 기술적 지속성은 그가 제시한 요소가 아니다":"제도와 기술은 그가 꼽은 지속성의 갈래에 들지 않아요.","제한시간 초과 주차, 지정구획 외 주차, 목적 외 이용":"제한시간을 넘겨 세우거나 지정한 구획 밖에 세우거나 주차 외 목적으로 쓰는 것이 금지됩니다.","제한해 쾌적성을 높이고 쿨데삭·환형도로를 이용할 수 있다":"통과교통을 막아 쾌적하게 만들고, 막다른 길이나 고리 모양 도로를 이용할 수 있습니다.","조경, 중심몰, 광경(랜드스케이프)은 린치의 구성요소가 아니다":"조경과 중심몰, 광경은 린치가 꼽은 도시이미지 요소에 해당하지 않아요.","조사·분석단계는 답사와 통계자료로 기초조사를 하는 단계":"조사·분석단계에서는 현지 답사와 통계자료로 기초조사를 해요.","조성원가 수준으로 공급하며 공급받은 용도대로 건설해야 한다":"국민주택 건설용지는 조성원가 수준으로 공급하며, 받은 용도 그대로 건설해야 합니다.","조세 수입 확보는 국토개발의 목적이 아니다":"세금을 더 걷는 일은 국토개발이 추구하는 목적이 아닙니다.","조세정책이 아닌 금융정책만으로 개발을 촉진·지연시키는 것은 아니며, 민간부문도 사업 실패 위험을 진다":"금융정책만으로 개발을 촉진하거나 지연시키는 것이 아니며, 조세정책도 쓰고 민간부문도 사업 실패 위험을 집니다.","존의 경계는 간선도로와 일치시킨다":"존을 나눌 때 경계선은 간선도로를 따라 긋습니다.","존의 크기를 인구규모와 무관하게 동일하게 하거나 다양한 통행특성을 한 존에 섞는 것은 바람직하지 않다":"존의 크기를 인구규모와 상관없이 같게 하거나 통행특성이 다른 곳을 한 존에 섞는 것은 바람직하지 않습니다.","종단점법·방안법·지성선법은 간접 등고선 측량법이며 레벨법은 직접법이다":"종단점법, 방안법, 지성선법은 간접법이고 레벨법은 직접법입니다.","종전 토지의 합필·소유자 합의·확정측량 결과에 따른 변경":"합필을 하거나 소유자끼리 합의하거나 확정측량으로 바뀐 경우에는 인가 없이 환지계획을 고칠 수 있어요.","종주도시권의 다핵개발은 자유방임보다 오히려 대도시 집중을 더 유발할 수 있다":"종주도시권에서 다핵개발을 하면 자유방임일 때보다 오히려 대도시 집중이 더 심해질 수 있어요.","종주도시 내 신규 시설 설치·수리를 제한해 노후화되도록 방치하는 정책이다":"하바나전략은 종주도시 안에 새 시설을 짓거나 고치지 못하게 막아 낡도록 놓아두는 정책이에요.","주간선도로는 대량 통과교통을, 보조간선도로는 교통 집산 기능을 한다":"주간선도로는 많은 통과교통을 처리하고, 보조간선도로는 교통을 모으고 나누는 일을 해요.","주간선도로·특수도로·국지도로이며 지하도로는 입체 분류에 속한다":"기능별 분류는 주간선도로, 특수도로, 국지도로이며 지하도로는 입체 분류에 속해요.","주거기능 보호를 위한 완충공간·동선 분리가 필요 없는 것은 아니며, 이는 오히려 과제다":"주거기능을 보호할 완충공간과 동선 분리가 필요 없는 것이 아니라, 오히려 풀어야 할 과제입니다.","주거단지 내 공원·녹지는 대기·수질 오염을 정화하고 미기후를 조절하며 재난을 완화한다":"단지 안 공원과 녹지는 공기와 물을 맑게 하고 미기후를 고르며 재난 피해를 줄입니다.","주거·상업·자연녹지지역은 1만㎡ 이상, 공업지역은 3만㎡ 이상이면 지정할 수 있다":"도시개발구역은 주거·상업·자연녹지에서 1만㎡ 이상, 공업지역에서 3만㎡ 이상일 때 지정합니다.","주거·상업지역에만 한정되지 않으며 건폐율·용적률을 강화해 적용할 수 있다":"주거지역과 상업지역에만 한정되지 않으며, 건폐율과 용적률을 더 엄격히 적용할 수 있습니다.","주거지 관리계획, 현황조사, 건폐율·용적률 등 밀도계획이 포함된다":"정비기본계획에는 주거지 관리계획, 현황조사, 건폐율·용적률 등 밀도계획이 들어갑니다.","주거지형 50만㎡ 이상, 중심지형 20만㎡ 이상 등 면적기준이 있다":"재정비촉진지구는 주거지형 50만㎡ 이상, 중심지형 20만㎡ 이상처럼 면적기준이 있습니다.","주거환경개선·재개발·재건축사업이며 아파트지구개발사업은 아니다":"정비사업은 주거환경개선, 재개발, 재건축이며 아파트지구개발사업은 포함되지 않습니다.","주된 성격은 경관관리계획이 아니라 토지이용 합리화 등을 포괄하는 종합계획이다":"경관을 관리하는 계획이 아니라 토지이용을 합리화하는 등 여러 내용을 아우르는 종합계획입니다.","주민발의, 개발협정, 주민투표":"주민참여형 도시개발에는 주민발의, 개발협정, 주민투표가 있어요.","주민은 기반시설이나 지구단위계획구역 지정·변경을 제안할 수 있으나 용도지역 변경은 제안할 수 없다":"주민이 제안할 수 있는 것은 기반시설과 지구단위계획구역이고, 용도지역을 바꿔 달라는 제안은 불가능합니다.","주민의 주거·생업·영농 목적 토지이용은 예외로 취급된다":"주민이 살거나 생업이나 농사를 위해 땅을 쓰는 경우는 예외로 다룹니다.","주민·전문가 의견을 듣고 광역시장·도지사가 작성한다":"광역개발사업계획은 주민과 전문가 의견을 들어 광역시장이나 도지사가 작성합니다.","주민참여를 수반하며 비물리적 요소까지 분석하고 공공·민간 부문 시행계획을 함께 수립한다":"도시설계는 주민이 참여하고, 물리적이지 않은 요소도 분석하며, 공공과 민간의 시행계획을 함께 짭니다.","주민참여형 도시개발 유형으로 분류되지 않는다":"공공협약은 주민참여형 도시개발 유형으로 분류하지 않습니다.","주택법 사업계획 승인을 받으면 실시계획 인가, 도시·군관리계획 결정, 사업시행자 지정이 의제 처리된다":"사업계획 승인을 받으면 실시계획 인가와 도시·군관리계획 결정과 시행자 지정까지 받은 것으로 칩니다.","주택 수 10호 이상, 1만㎡당 호수밀도 10호 이상이다":"취락지구는 주택이 10호 이상이고 1만㎡당 호수밀도가 10호 이상일 때 지정합니다.","주택유형·단지규모·단지환경에 따라 달라진다":"주택용지가 전체에서 차지하는 비율은 주택 유형, 단지 규모, 단지 환경에 따라 달라집니다.","주택 유형·밀도·비용을 혼합 배치하고 역 보행거리 내에 주거·상업시설을 둔다":"주택 유형, 밀도, 비용을 섞어 배치하고 역에서 걸어갈 거리 안에 주거와 상업시설을 둡니다.","주택을 종교시설·고아원으로, 공장을 연구소·교육원으로 바꾸는 것은 허가받아 가능하지만 노래연습장 용도변경은 금지된다":"주택을 종교시설이나 고아원으로, 공장을 연구소나 교육원으로 바꾸는 것은 허가받아 하지만 노래연습장으로는 못 바꿉니다.","주택재개발·재건축·주거환경개선사업이며 리모델링사업은 아니다":"정비사업에는 주택재개발, 재건축, 주거환경개선이 있고 리모델링사업은 빠집니다.","죽목의 벌채·식재, 물건 장기 적재, 토지분할은 허가가 필요하나 경작용 형질변경은 아니다":"나무를 베고 심거나 물건을 오래 쌓거나 땅을 나누려면 허가가 필요하지만 경작용 형질변경은 필요 없습니다.","죽목의 재식·간벌은 예외적으로 허용된다":"나무를 심거나 솎아 베는 일은 예외적으로 허용됩니다.","준공과 동시에 국가에 소유권이 귀속되고 민간이 직접 운영해 투자비를 회수한다":"BTO는 완공과 동시에 소유권이 국가로 넘어가고 민간이 직접 운영하면서 투자비를 되찾습니다.","준공과 동시에 국가에 소유권이 귀속되고 사업자가 운영권을 갖는다":"BTO는 완공과 동시에 소유권이 국가로 가고 사업자는 운영권을 갖습니다.","준공 후 일정 기간 사업시행자가 소유권을 보유하다 만료 시 국가에 이전한다":"BOT는 준공 뒤 일정 기간 사업시행자가 소유권을 갖다가 기간이 끝나면 국가에 넘기는 방식입니다.","준공 후 정부에 소유권을 이전하는 임대형 방식이지 기존 시설 정비자에게 소유권을 주는 제도가 아니다":"BTL은 완공 후 정부에 소유권을 넘기는 임대형이고, 기존 시설을 정비한 사람에게 소유권을 주는 제도는 아닙니다.","중심대광장은 교통광장이 아니라 일반광장이다":"중심대광장은 일반광장 쪽이며 교통광장에 넣지 않아요.","중심대도시와 경제·사회·문화적으로 통합된 일상생활권이다":"대도시권은 중심 대도시와 경제, 사회, 문화적으로 하나가 된 일상 생활권입니다.","중심도시와 일정 비율 이상 출퇴근자를 갖는 주변 지역을 묶은 노동시장 기반 지역이다":"SMSA는 중심도시에 일정 비율 이상 통근하는 주변 지역을 묶어 노동시장을 기준으로 정한 지역입니다.","중심부를 고층·고밀화하고 넓은 오픈스페이스를 확보한다":"빛나는 도시는 중심부를 고층·고밀화하고 넓은 오픈스페이스를 확보하는 구상이에요.","중심지미관지구·역사문화미관지구·일반미관지구로 나뉘며 시가화미관지구는 없다":"미관지구는 중심지, 역사문화, 일반 미관지구로 나뉘며 시가화미관지구라는 구분은 없습니다.","중앙공원이라는 세분은 도시공원 및 녹지법에 없다":"도시공원 및 녹지법에는 중앙공원이라는 세분이 없습니다.","중앙행정기관 및 그 소속기관의 청사는 건축물 연면적 1,000㎡ 이상이면 인구집중유발시설이다":"청사는 연면적이 1,000㎡ 이상이어야 사람을 몰리게 하는 시설로 칩니다.","증축은 기존 건축물의 면적·층수·높이를 늘리는 것, 신축은 멸실된 대지에 새로 짓는 것이다":"증축은 기존 건축물의 면적, 층수, 높이를 늘리는 것이고 신축은 건물이 없어진 대지에 새로 짓는 것입니다.","지구공원이라는 세분은 도시공원법상 존재하지 않는다":"도시공원법에는 지구공원이라는 세분 항목이 없어요.","지구단위계획구역과 지구단위계획은 도시관리계획으로 결정한다":"구역과 계획 모두 도시관리계획 절차로 결정합니다.","지구단위계획에 포함해 결정한다":"특별계획구역은 지구단위계획에 포함해 함께 결정해요.","지구 수준의 문제 해결을 우선하고 기성시가지 유형별 대책을 세운다":"상향적 접근은 지구 수준의 문제를 먼저 풀고 기성시가지 유형에 맞는 대책을 세웁니다.","지대는 시장까지 거리로 결정되며, 거리가 멀수록 인구밀도와 지대 모두 낮아진다":"튀넨의 지대이론은 시장까지의 거리로 지대를 정하며 멀어질수록 인구밀도와 지대가 함께 낮아집니다.","지대·생산비·운송비로 정해진다":"튀넨의 이론에서 재배작물의 유형은 지대, 생산비, 운송비로 정해집니다.","지리·공간정보를 저장·검색·분석하며 인력·시설 측면까지 포괄한다":"지리와 공간 정보를 저장하고 찾아 분석하는 체계로, 사람과 시설까지 포함한 개념입니다.","지방 계획자치권이 침해되고 상위계획이 지나치게 하향적·독주적이다":"우리나라는 지방의 계획 자치권이 침해되고 상위계획이 지나치게 위에서 아래로 일방적이라는 문제가 있어요.","지방분산형 국토골격, 통일 대비 국토기반 조성, 국민복지 향상":"이 계획은 목표를 지방분산형 골격, 통일 대비 기반, 복지 향상의 세 방향으로 잡았습니다.","지방양여금, 국고보조금, 주민세·재산세는 도시자치단체의 재원이며 법인세·교통세는 국세다":"양여금, 보조금, 주민세, 재산세는 자치단체가 쓰는 재원이고 법인세와 교통세는 국가가 걷는 세금입니다.","지방정부가 아니라 국가가 주체가 되어 수립한다":"국토계획은 지방정부가 아니라 국가가 주체로 나서서 세웁니다.","지상공간 활용과 복합고밀 개발을 지향하며 자동차 중심 저밀도 개발은 추구하지 않는다":"지상 공간을 알뜰히 쓰며 복합 고밀 개발을 지향하고, 자동차 중심의 저밀도 개발은 따르지 않습니다.","지상교통의 원활한 소통과 인구집중지역의 교통처리를 위해 설치한다":"지하도로는 지상교통을 원활하게 하고 사람이 몰린 지역의 교통을 처리하려고 설치합니다.","지상권·지역권·전세권은 토지보상법상 토지 관계인의 권리이며 지하권은 아니다":"토지 관계인의 권리는 지상권, 지역권, 전세권이고, 지하권은 여기에 넣지 않아요.","지속가능한 녹색국토, 상생하는 균형국토, 경쟁력있는 개방국토가 있다":"수정계획의 기본목표 중 세 가지가 녹색국토, 균형국토, 개방국토입니다.","지역 간 생산요소 이동을 성장요인으로 보며 중심-주변 종속관계는 중시하지 않는다":"신고전 이론은 지역 사이 생산요소 이동이 성장의 원인이라고 보고, 중심과 주변의 종속은 중시하지 않아요.","지역경제를 수출(기반)부문과 지원(비기반)부문으로 나누고 다양한 공간에 적용된다":"지역경제를 밖으로 파는 기반 부문과 안에서 쓰이는 비기반 부문으로 나누는 이론이며 여러 공간 규모에 쓸 수 있습니다.","지역경제를 수출산업과 수입(지역 내 소비)산업으로 구분하며 공공부문에도 적용된다":"수출기반모형은 지역경제를 수출산업과 지역 내 소비 산업으로 구분하고 공공부문에도 적용합니다.","지역경제 변화의 원인을 구조적 요인과 지역 고유 경쟁력으로 구분할 수 있다":"구조적인 이유와 지역만의 경쟁력으로 지역경제 변화의 원인을 가를 수 있어요.","지역계획이 아니라 도시계획 범주다":"도시관리계획은 지역계획이 아니라 도시계획에 속합니다.","지역공동체의식 희박화와 개인주의 팽배도 과밀도시 문제다":"지역공동체의식이 약해지고 개인주의가 퍼지는 것도 과밀도시의 문제입니다.","지역발전을 위한 쇄신 확산은 성장거점도시 개발을 촉진하는 방법으로 이루어진다":"성장거점도시를 키우는 방식으로 쇄신이 지역에 퍼지게 합니다.","지역산업 변화를 국가성장효과, 산업구조효과, 지역경쟁력효과로 나눈다":"변이할당분석은 변화를 국가의 성장, 산업구조, 지역의 경쟁력 세 효과로 쪼개 봅니다.","지역성장의 횡적(산업구조)·종적(시차) 차원을 동시에 파악할 수 있다":"변이할당분석은 지역성장을 산업구조라는 가로 축과 시간 차라는 세로 축에서 한꺼번에 파악합니다.","지역 외부의 수요가 지역경제 성장을 유도한다고 보며 개방된 경제체제에는 성립하기 어렵다":"지역 밖의 수요가 지역경제 성장을 이끈다고 보며, 열려 있는 경제체제에서는 성립하기 어렵습니다.","지역을 동질지역·결절지역·계획지역으로 나누며 낙후지역은 포함되지 않는다":"부데빌은 지역을 세 갈래로 나누며, 그 안에 낙후지역이라는 갈래는 없습니다.","지역의 쇄신 채택률을 수리모형으로 설명하려 했다":"모릴은 지역이 쇄신을 받아들이는 비율을 수리모형으로 설명하려고 했습니다.","지역의 연구소·금융기관이나 도로·공항·통신망은 상부구조가 아니라 하부구조다":"지역의 연구소, 금융기관, 도로, 공항, 통신망은 상부구조가 아니라 하부구조에 해당해요.","지역의 조직·제도, 문화, 규범이다":"상부구조는 지역의 조직과 제도, 문화, 규범을 말합니다.","지역적 문제의 심각성 인식과 이론적 발전, 산업화·도시화에 따른 기능적 문제":"지역 문제가 심각하다는 인식과 이론의 발전, 산업화와 도시화로 생긴 기능적 문제가 배경이에요.","지역주의·지방주의에 부응하려는 요구도 지역계획의 형성 배경이며 국민 소비성향 억제는 아니다":"지역주의와 지방주의의 요구도 계획을 만들게 한 배경이며, 소비성향을 누르려는 것은 아닙니다.","지역·지구·구역 지정과 세금·보조금이며 도시개발사업은 직접적 수단이다":"지정이나 세금, 보조금은 간접 수단이고, 도시개발사업은 직접 수단에 속해요.","지역특성·계획방향, 토지이용·개발, 공간구조·생활권·인구배분을 담는다":"도시기본계획에는 지역 특성과 계획 방향, 토지이용과 개발, 공간구조와 생활권, 인구 배분이 들어갑니다.","지적 엘리트와 전문가로 구성되며 1차 산업 비율이 낮고 2·3차 산업 비율이 높다":"지적 엘리트와 전문가가 모여 있고 1차 산업 비율이 낮으며 2·3차 산업 비율이 높아요.","지정·고시된 구역은 국토계획법상 결정·고시로 의제되지만 모든 경우 지방의회 의견까지 필요한 것은 아니다":"구역이 지정되면 결정·고시로 보지만 지방의회의 의견까지 늘 받아야 하는 것은 아닙니다.","지정 고시일로부터 3년 이내 계획을 수립하지 않으면 구역 지정의 효력을 잃는다":"지정을 고시한 날부터 3년 안에 계획을 세우지 않으면 구역 지정이 효력을 잃습니다.","지정된 차량 출입구 준수는 인센티브 대상이 아니다":"정해 둔 차량 출입구를 지키는 것은 인센티브를 받을 사항이 아닙니다.","지하도로·보행자전용도로·자전거전용도로이며 보차공존도로는 아니다":"사용 형태별로는 지하도로, 보행자전용도로, 자전거전용도로가 있고 보차공존도로는 포함되지 않습니다.","지형(등고선)을 고려해 건물을 배치하고 여름철 바람 방향을 고려한다":"지형(등고선)을 살펴 건물을 놓고 여름철 바람이 부는 방향도 고려해요.","지형도면 고시는 의제 처리 대상이 아니다":"지형도면 고시는 사업계획 승인으로 받은 것으로 치는 항목에 들지 않아요.","지형이 평탄한 고대·중세 봉건도시에 흔하다":"격자형은 지형이 평탄한 고대와 중세의 봉건도시에 흔합니다.","직선 중심의 계획과 엄격한 용도규제를 통한 기능분리는 중세가 아니라 근대적 특성이다":"곧은길 중심 계획과 엄격한 용도 규제로 기능을 떼어 놓는 것은 중세가 아니라 근대 도시의 특성이에요.","직주근접을 실현해 교통혼잡에 따른 사회적 비용을 줄인다":"직장과 집이 가까워지면 교통혼잡 때문에 드는 사회적 비용이 줄어요.","진보된 기술을 쓰는 동적 산업으로 다른 산업과 연계가 강하고 소득탄력성이 높다":"선도산업은 새 기술로 움직이는 역동적 산업으로 다른 산업과 얽힘이 많고 소득이 늘면 수요가 크게 느는 성격을 지닙니다.","집적이익 추구도 국토관리의 기본이념으로 명시되지 않았다":"집적의 이익을 따르는 것은 국토관리의 기본이념으로 내세운 적이 없습니다.","징수된 부담금은 조사·연구 등 관리 비용에 쓰이며 부과·징수권자가 시장·군수인 것은 아니다":"걷은 부담금은 조사와 연구 등 관리에 쓰이고, 걷는 주체가 시장이나 군수라고 정해진 것은 아닙니다.","차량의 원활한 소통과 혼잡 완화를 위해 설치한다":"교차점광장은 차량이 원활히 흐르고 혼잡이 덜하도록 설치합니다.","차량 중심 접근성이나 계층별 편익시설 제공":"물리적 목표는 차량 중심의 접근성을 높이고 생활권 계층별로 편익시설을 갖추는 것입니다.","참여 유형이 아니라 재원조달 방식이다":"BTL은 주민이 참여하는 유형이 아니라 돈을 마련하는 재원조달 방식이에요.","천재지변 등 긴급한 사유, 도시계획사업과 병행, 순환정비방식이 필요하면 시장·군수가 직접 시행할 수 있다":"천재지변 같은 긴급한 사유가 있거나 도시계획사업과 함께 하거나 순환정비방식이 필요하면 시장과 군수가 직접 시행할 수 있습니다.","청소년수련시설, 학교, 사회복지시설이며 시장은 유통·공급시설이다":"청소년수련시설, 학교, 사회복지시설은 공공·문화체육시설이고, 시장은 유통·공급시설에 속해요.","체비지 증가에 따른 환지계획 변경":"체비지가 늘어나서 환지계획을 바꾸는 경우에는 인가가 필요합니다.","초기 설치비용은 절감되지 않고 오히려 크게 든다":"처음 설치할 때 드는 비용은 줄지 않고 오히려 크게 듭니다.","초기투자비가 크고 이주대책 마련이 어렵다":"수용·사용방식은 처음 들어가는 돈이 많고 이주대책을 마련하기가 어렵습니다.","초등학교 1개교를 유치할 인구 규모로 간선도로에 둘러싸인다":"초등학교 하나가 필요한 인구를 단위로 하며 주위를 간선도로가 둘러쌉니다.","초등학교는 근린주거구역 단위로, 중·고등학교는 2개 근린주거구역당 1개 비율로 배치한다":"초등학교는 근린주거구역마다, 중·고등학교는 두 근린주거구역에 하나꼴로 배치합니다.","초등학교와 체육시설은 정비기반시설에 포함되지 않는다":"초등학교와 체육시설은 정비기반시설로 보지 않습니다.","초등학교·작은공원·운동장·작은가게 등을 갖춘 물리적 기본단위다":"페리의 근린주구는 초등학교, 작은공원, 운동장, 작은가게 등을 갖춘 물리적 기본단위입니다.","초등학교 통학거리를 1,000m, 소음도를 80dB로 아는 것은 이 규정의 정확한 기준이 아니다":"통학거리 1,000m와 소음 80dB은 이 규정이 정한 정확한 기준값이 아닙니다.","총체적 자료에 의존해 계획가의 주관이 개입될 여지가 있다":"집계된 자료에 기대기 때문에 계획하는 사람의 판단이 들어갈 수 있는 한계가 있어요.","최대 길이를 제한하는 이유는 통행 효율·편익시설 접근·피난 용이성 때문이다":"막힌 도로의 길이를 제한하는 까닭은 통행이 효율적이고 편의시설에 닿기 쉬우며 피난이 쉽기 때문입니다.","최소 대지면적은 3ha 이상이 되어야 한다":"아파트단지를 이루려면 최소 대지면적이 3ha 이상이어야 합니다.","최저고도지구는 문화재 보전 목적의 용도지구가 아니다":"문화재를 보전하려고 지정하는 지구에 최저고도지구는 들어가지 않습니다.","최적의 대안보다 지속적인 조정과 적응으로 목표를 추구한다":"점진적 계획은 최고의 대안을 찾기보다 계속 조정하고 적응하면서 목표를 향해 갑니다.","축척 1/500 도면을 1/1,000으로 축소":"축척 1/500 도면을 1/1,000으로 줄이는 경우를 말합니다.","충분한 규모에서 혼합 토지이용과 공동 오픈스페이스 확보가 용이하다":"충분히 큰 규모로 개발하면 용도를 섞기 쉽고 공동 오픈스페이스도 확보하기 쉽습니다.","취락지구의 지정·정비에 관한 사항을 포함해야 한다":"관리계획에는 취락지구를 지정하고 정비하는 사항이 들어가야 합니다.","취락지구정비사업 시행 시에는 국토계획법에 따라 제1종 지구단위계획구역으로 지정한다":"취락지구정비사업을 하면 첫째 유형 지구단위계획구역으로 지정됩니다.","카르도와 데쿠마누스로 짜인 격자가로망":"로마 도시는 카르도와 데쿠마누스 두 길이 직각으로 짜인 격자 가로망이었습니다.","쾌적한 환경을 찾아 농촌으로 이동하는 현상이 나타난다":"반도시화 단계에서는 쾌적한 환경을 찾아 농촌으로 옮겨 가는 현상이 나타납니다.","쿨데삭으로 연결되어 주택의 전후가 바뀌는 것이 특징이다":"막다른 길로 이어지고 주택의 앞뒤가 바뀐 배치가 래드번 주택의 특징입니다.","쿨데삭형은 통과교통을 차단해 안전성이 높고 루프형은 세도로 교차점이 적다":"쿨데삭형은 지나가는 차를 막아 안전하고, 루프형은 작은 도로끼리 만나는 교차점이 적어요.","크리스탈러는 시장·교통·행정 3가지 원리로 중심지가 확대된다고 보았다":"크리스탈러는 시장, 교통, 행정 세 원리에 따라 중심지가 확대된다고 보았어요.","크리스탈러·뢰쉬의 중심지이론에서 규모의 경제, 수요 밀도, 수송비용으로 정해진다":"크리스탈러와 뢰쉬는 규모의 경제, 수요 밀도, 수송비용이 시장권 크기를 정한다고 봤어요.","타당성분석이 사업의 확실한 성공을 보장하는 것은 아니다":"타당성분석을 거쳤다고 해서 사업이 반드시 성공한다고 보장되지는 않아요.","태백권·대구권·제주권이 있고 대전권은 없다":"태백권, 대구권, 제주권은 첫 번째 계획의 권역이고 대전권은 이 목록에 없습니다.","태양과 기후에 효율적으로 대처하는 구조를 찾는 것이며 식생이 가장 큰 영향 요소는 아니다":"향을 분석하는 것은 해와 기후에 효율적으로 대처하는 구조를 찾으려는 것이고, 식생이 가장 큰 요소는 아닙니다.","택지개발·개발촉진지구·대지조성사업이고 도시환경정비사업은 도시계획사업이다":"택지개발, 개발촉진지구, 대지조성사업은 도시계획사업이 아닌 쪽이고, 도시환경정비사업은 도시계획사업입니다.","택지개발·주택지조성사업, 도시재개발사업, 도시철도건설사업":"택지개발, 주택지조성사업, 도시재개발사업, 도시철도건설사업을 하면 노외주차장을 의무로 설치해야 합니다.","토지 공급 부족, 과밀 완화, 혐오시설의 지하 배치":"토지 공급이 모자라고 도시 과밀을 풀어야 하며 혐오시설을 땅 밑에 두려는 것이 개발 배경이에요.","토지를 소유하지 않은 주민이 유리한 제도는 아니다":"땅이 없는 주민에게 특별히 유리한 제도가 되는 것은 아닙니다.","토지를 합리적으로 이용하기 위해 필요하면 둘 이상의 도시계획시설을 같은 토지에 함께 결정할 수 있다":"땅을 합리적으로 쓰려면 같은 땅에 두 개 이상의 도시계획시설을 겹쳐 결정하기도 합니다.","토지를 효율적으로 쓰고 도로 면적을 줄이며 보차분리가 가능하다":"슈퍼블록은 땅을 효율적으로 쓰고 도로 면적을 줄이며 사람과 차를 나누어 다니게 할 수 있어요.","토지소유자 7인 이상이 정관·사업계획을 정해 지정권자의 인가를 받아 설립한다":"토지소유자 7인 이상이 정관과 사업계획을 정해 인가를 받으면 도시개발조합을 설립할 수 있어요.","토지소유자 합의나 합필·분필에 의한 변경은 경미한 변경이나 체비지 증가는 아니다":"합의나 합필·분필로 인한 변경은 가벼운 변경에 들지만, 체비지가 늘면 가벼운 변경이 아닙니다.","토지수용은 전면매수·부분매수·환지방식이 있으며 개발시기는 단계적·전면 개발로 나뉜다":"토지수용은 전면매수, 부분매수, 환지방식이 있고 개발 시기는 단계적 개발과 전면 개발로 나뉘어요.","토지의 소유권과 개발권을 구분해 거래하며 송출·수용지역 간 개발이익을 분배한다":"토지 소유권과 개발권을 나눠 거래하며 개발권을 내놓는 지역과 받는 지역 사이에 개발이익을 나눕니다.","토지이용(개발)은 교통수요를 유발한다":"개발이 일어난 토지로 사람이 오가기 때문에 교통수요가 새로 생깁니다.","토지이용 개발 및 방재에 관한 사항은 광역도시계획의 직접 내용이 아니다":"토지이용 개발과 방재는 광역도시계획이 직접 정하는 사항이 아닙니다.","토지이용 결정 시 경제성·보건성·쾌적성을 들었다":"샤핀은 토지이용을 결정할 때 따질 공공이익으로 경제성, 보건성, 쾌적성을 꼽았어요.","토지이용계획이 도시의 외연적 확산을 촉진하는 것은 아니다":"토지이용계획은 도시가 바깥으로 번지는 것을 부추기지 않습니다.","토지이용과 교통은 체인처럼 상호의존적인 순환관계를 가지며, 교통시설 확충이 토지이용에 부정적 외부효과만 낳는 것은 아니다":"토지이용과 교통은 서로를 낳는 순환 관계이며, 교통시설이 늘면 토지이용에 나쁜 외부효과만 생기는 것은 아닙니다.","토지이용규제, 시장진입·거래 규제, 부담금 부과로 도시개발에 개입한다":"공공부문은 토지이용을 규제하고, 시장 진입과 거래를 규제하고, 부담금을 부과하면서 도시개발에 개입해요.","토지이용 규제 수단으로 용도지역·용도지구·용도구역을 둔다":"용도지역, 용도지구, 용도구역은 땅 쓰임을 규제하려고 마련한 세 가지 틀이에요.","토지이용 중심의 정적인 공간구성형태는 동태적 요소가 아니다":"동태적이 아닌 정적인 공간구성은 토지이용에 초점을 두며 린치의 동태적 요소에 해당하지 않습니다.","토지이용 효율화와 공공재 남용 방지가 도시계획의 필요성이며 개인적 목표 달성은 아니다":"토지이용을 효율화하고 공공재가 남용되는 것을 막는 것이 필요성이며 개인의 목표 달성은 아닙니다.","토지적성평가·일반조사·환경성검토로 구성되며 도심지는 일부를 생략할 수 있다":"기초조사는 토지적성평가, 일반조사, 환경성검토로 이루어지고 도심지에서는 일부를 줄일 수 있습니다.","토지취득방식이 아니라 시행주체에 따른 구분이다":"섹터 구분은 누가 사업을 하느냐의 구분이어서, 땅을 어떻게 얻느냐를 나눈 취득방식이 아닙니다.","토지 형질변경, 토석 채취, 식재, 물건 적재도 도시공원 점용허가 대상이다":"땅의 형질을 바꾸거나 토석을 캐거나 나무를 심거나 물건을 쌓는 일도 점용허가를 받아야 합니다.","통로·가장자리(경계)·지구·결절점·랜드마크":"린치는 통로, 가장자리(경계), 지구, 결절점, 랜드마크의 다섯 가지를 도시이미지 요소로 꼽았습니다.","통신설비 배치방식에 따라 중심배치형·외곽배치형·분리배치형으로 나뉜다":"텔레포트단지는 통신설비를 어디에 두느냐에 따라 중심배치, 외곽배치, 분리배치로 나뉩니다.","통일된 개념이 없고 국가에 따라 다르다는 한계가 있다":"기본수요에는 통일된 개념이 없고 나라마다 다르다는 한계가 있어요.","통제주의 국가는 국토계획에, 조정주의 국가는 지역계획에 중점을 둔다":"통제주의 국가는 국토계획 쪽을, 조정주의 국가는 지역계획 쪽을 더 중시합니다.","투기과열지구 지정·전매제한, 리모델링 특례, 최저주거기준 미달가구 지원":"주택법이 다루는 일로는 투기과열지구와 전매제한, 리모델링 특례, 최저주거기준 미달가구 지원이 있습니다.","투기적 매입자 개입에 따른 불로소득, 공공감보 기준 불명확, 환지 후 지가 차이로 민원이 생길 수 있다":"투기꾼이 끼어 생기는 불로소득, 불명확한 공공감보 기준, 환지 뒤 지가 차이가 민원을 부를 수 있습니다.","투입·산출 개념을 처음 시도한 사람은 케네(Quesnay)다":"투입과 산출을 처음 따져 본 사람은 프랑스의 케네입니다.","투입산출분석은 생산·산업구조 예측과 지역 간 산업연관 분석, 경제 총량계획에 쓰인다":"투입산출분석은 생산과 산업구조를 내다보고, 지역끼리의 산업 연관과 경제 총량계획에 활용됩니다.","투자기업·관광객·주민이며 지방자치단체 자체는 고객이 아니다":"도시마케팅의 고객은 투자기업, 관광객, 주민이고 지방자치단체 자체는 고객이 아닙니다.","투자재원이 허용하면 NPV가 높은 사업을 우선하며, B/C비가 높다고 절대적으로 우선하는 것은 아니다":"투자재원이 허용하면 NPV가 높은 사업을 먼저 하고, B/C비가 높다고 무조건 앞서는 것은 아닙니다.","투자효과가 큰 지역만 집중 개발하는 것은 국토관리 기본이념이 아니다":"투자 효과가 큰 곳만 골라 개발하자는 것은 국토관리의 기본이념에 어긋납니다.","특별시장·광역시장·시장·군수가 관리한다":"공동구는 특별시장, 광역시장, 시장, 군수가 관리합니다.","특별시장·군수·구청장은 노상주차장을 설치할 수 있으나 도지사는 아니다":"노상주차장은 특별시장, 군수, 구청장이 설치할 수 있고 도지사는 해당하지 않습니다.","특정지역개발계획·개발촉진지구개발계획·수도권발전계획이며 광역도시계획은 별도다":"지역계획은 특정지역, 개발촉진지구, 수도권발전계획을 가리키고 광역도시계획과는 따로 봅니다.","특정지역계획, 광역권개발계획, 수도권정비시행계획":"특정지역계획과 광역권개발계획과 수도권정비시행계획이 지역계획의 범주예요.","파리 소재 대학의 지방 이전은 파리권 집중억제 정책이다":"파리 소재 대학을 지방으로 옮기는 것은 파리권 집중을 억제하는 정책에 속해요.","판매시설용지처럼 영리 목적 용지는 공개 추첨이 아닌 다른 방식으로 공급한다":"판매시설용지 같은 영리용 땅은 추첨이 아니라 다른 방식으로 넘깁니다.","팔란스테르(단일건물 이상도시, 르두나 오웬이 아니다)":"푸리에가 그린 이상도시는 한 건물에서 함께 사는 팔란스테르이고, 르두나 오웬의 안이 아닙니다.","편익-비용비(B/C), 순현재가치(NPV), 내부수익률(IRR)":"비용편익분석의 구체적 방법에는 B/C비, 순현재가치, 내부수익률이 있어요.","평가지표와 프로젝트의 비용·수입 추정이 기본이며 세금·이자는 제외한다":"사업성분석은 평가지표를 쓰고 비용과 수입을 추정하는 일이 바탕이며, 세금과 이자는 따지지 않습니다.","평균층수가 높아지면 용적률도 높아진다":"건폐율이 같다면 평균층수가 높아질수록 용적률도 올라갑니다.","평균 통행거리는 5km 미만, 유출입 지점 평균간격은 500m 정도로 한다":"보조간선도로는 평균 통행거리가 5km 미만이고 유출입 지점 사이는 평균 500m쯤 둡니다.","평탄한 지형, 균등한 구매력 분포, 거리에 비례하는 운송비":"평탄한 지형, 고른 구매력 분포, 거리에 비례하는 운송비를 기본 가정으로 둡니다.","평탄한 지형에 형성되었고 넓고 체계적인 도로망을 갖추었으며 시저는 마차 주간통행금지법을 시행했다":"평탄한 지형에 세워져 넓고 체계적인 도로망을 갖췄고 시저가 마차 주간통행금지법을 시행했어요.","폭 12m~20m 범위이며 25m는 대로에 속한다":"중로는 폭이 12m 이상 20m 사이이고 25m는 대로에 속해요.","표면·단면·고저차 수준측량은 측량 목적에 따른 분류이며 직접수준측량은 방법에 따른 분류다":"측량의 목적으로 나눈 것이 표면, 단면, 고저차 수준측량이고, 직접수준측량은 측정 방식으로 나눈 이름입니다.","표척 조정의 잘못에 의한 오차는 개인오차이고 기포 감도 불량·지구곡률은 다른 오차다":"표척을 잘못 맞춘 오차는 사람 탓에 생기는 개인오차이고, 기포 감도와 지구곡률은 다른 종류 오차예요.","플로리다의 창조도시 3대 지표는 인재(Talent)·기술(Technology)·관용성(Tolerance)이다":"플로리다가 든 창조도시의 세 가지 지표는 인재, 기술, 관용성이에요.","피해구제 절차처럼 계획가가 약자의 이익을 대변하는 것이다":"옹호적 계획은 피해를 구제하는 절차처럼 계획가가 약자의 이익을 대신 말하는 계획입니다.","필지나 획지별로 차등을 두지 않고 전체를 획일적으로 규제하는 것은 아니다":"필지나 획지마다 차등을 두며, 모두 똑같이 획일적으로 규제하는 것은 아닙니다.","하나의 건축물을 2필지 이상에 걸쳐 짓거나 도시계획시설을 지을 때는 2필지를 하나의 대지로 본다":"건물 하나를 두 필지 이상에 걸쳐 짓거나 도시계획시설을 짓는 경우에는 두 필지를 합쳐서 한 대지로 취급해요.","하향식·다목적·물리적 성격이 강하며 명령적 계획은 아니다":"하향식에 다목적이며 물리적 성격이 강하고, 명령으로 정하는 계획은 아닙니다.","학교는 일조·통풍·배수가 잘 되는 지역에 설치한다":"학교는 햇빛이 잘 들고 바람이 잘 통하고 물이 잘 빠지는 곳에 설치해요.","학교·항만·공항시설보호지구로 나뉜다":"시설보호지구는 학교, 항만, 공항 시설을 지키는 세 가지로 나뉩니다.","한 번 확정된 계획 내용을 고수하려는 자세는 바람직한 조정·관리가 아니다":"확정된 계획을 바꾸지 않고 끝까지 지키려는 태도는 바람직한 조정·관리가 못 됩니다.","한옥마을을 보존하려는 경우 주차장 설치기준을 100%까지 완화할 수 있다":"한옥마을을 지키려 할 때는 주차장을 의무 설치하는 기준을 전부 면제할 정도까지 줄여 줄 수 있습니다.","한 요소의 왜곡을 최소화하면 다른 요소의 왜곡은 오히려 커진다":"한 요소의 왜곡을 줄이면 다른 요소의 왜곡은 오히려 커지는 맞바꿈 관계입니다.","한 토지는 하나의 용도지역과 동시에 2개 이상의 지구로 지정될 수 있으나 용도지역은 하나만 가능하다":"하나의 토지에는 용도지역이 하나만 지정되지만, 지구는 동시에 둘 이상이 겹칠 수 있어요.","한 필지에 국한하지 않고 가구·획지 전체로 분산을 지양해 배치한다":"대지 안 공지는 한 필지에만 두지 않고 가구나 획지 전체에서 흩어지지 않게 모아 배치합니다.","합동재개발은 주민·건설업자·정부 3자가 공동 이익을 추구하며, 위탁재개발은 철거를 기본으로 정부가 건설업체를 알선한다":"합동재개발은 주민, 건설업자, 정부 세 주체가 이익을 함께 추구하고, 위탁재개발은 철거를 기본으로 정부가 건설업체를 소개해요.","합리성, 유기적 연대, 계약관계를 특징으로 하며 민속사회적 속성과는 거리가 멀다":"도시화가 진행되면 합리성, 유기적 연대, 계약관계가 두드러지고 민속사회의 성격은 옅어집니다.","합리적 계획과정, 목표-대안 관계, 계획집행 평가를 다룬다":"절차적 이론은 합리적 계획과정, 목표와 대안의 관계, 계획 집행의 평가를 다룹니다.","합병이 불가능해도 지번지역이 다르면 예외적으로 하나의 대지로 볼 수 있다":"합병할 수 없더라도 지번지역이 다르면 예외로 한 대지로 볼 수 있습니다.","해당 지방자치단체의 부시장·부지사가 맡는다":"시·도 도시계획위원회는 해당 지방자치단체의 부시장이나 부지사가 맡아요.","해리스와 울만의 다핵심이론은 도시가 여러 핵을 중심으로 성장한다고 본다":"해리스와 울만은 도시가 한 중심이 아니라 여러 핵을 중심으로 자란다고 봤습니다.","행정(Administrative) 존은 테크노폴리스의 구성요건이 아니다":"행정 구역은 테크노폴리스가 갖춰야 할 구성요건이 아닙니다.","행정·경제·문화의 중심지 기능을 담당한다":"도시는 행정, 경제, 문화의 중심지 구실을 합니다.","허가·인가 없이 한 행위는 처벌 대상이 된다":"허가나 인가를 받지 않고 행위를 하면 처벌받을 수 있습니다.","헤겟트의 기능결합 원칙 요소는 움직임·네트워크·결절이며 기후는 아니다":"기능결합 원칙의 요소는 움직임, 네트워크, 결절이며 기후는 여기에 속하지 않아요.","혁신적인 정보국토는 5대 기본목표에 포함되지 않는다":"혁신적인 정보국토는 5대 기본목표에 들어가지 않아요.","현대 도시관리는 공급자에서 수요자로, 물량에서 품질로, 무경쟁에서 경쟁으로 바뀐다":"도시관리의 흐름이 공급자에서 수요자로, 양에서 질로, 무경쟁에서 경쟁으로 옮겨 간다는 말이에요.","현상설계 등으로 창의적 개발안을 받아들이거나 복잡한 지형을 종합 개발할 때 지정한다":"현상설계로 창의적 안을 모으거나 지형이 복잡해 종합적으로 개발해야 할 때 지정해요.","현지조사·관찰·면접으로 얻는다":"조사자가 현장에서 직접 모은 자료입니다.","협력적 계획은 소수 전문가가 아니라 다양한 이해관계자의 상호작용을 강조한다":"협력적 계획은 몇몇 전문가보다 여러 이해관계자가 주고받는 과정을 중시합니다.","협의 요청을 받은 관계행정기관은 일정 기간 내 의견을 제시해야 한다":"협의를 요청받은 관계행정기관은 정해진 기간 안에 의견을 내야 합니다.","형식적 참여 단계이며 주민권력 단계가 아니다":"상담은 형식적으로 참여하는 단계이며 주민이 권력을 가지는 단계가 아닙니다.","혼용방식·환지방식·수용(사용)방식":"토지를 취득하는 방식은 환지방식, 수용(사용)방식, 그리고 둘을 섞은 혼용방식입니다.","확률적 요인은 리가 제시한 인구이동 변수에 포함되지 않는다":"리가 제시한 인구이동 변수에는 우연에 가까운 확률적 요인이 들어 있지 않아요.","환경계획 순으로 핵심 영역이 변화했다":"지역계획 이론은 환경계획에 이르기까지 핵심 영역이 차례로 바뀌어 왔습니다.","환경변화 관리자, 공공시설 건설 관리자, 정보·기술 지원자 기능을 한다":"도시정부는 환경변화를 관리하고 공공시설 건설을 관리하며 정보와 기술을 지원하는 기능을 합니다.","환경악화지역·안정지역·노후지역 등 노후도에 따라 구분된다":"재개발구역은 환경악화지역, 안정지역, 노후지역 등 낡은 정도에 따라 나눕니다.","환경오염을 최소화하는 이상적 형태로 직주근접과 관련 있다":"직장과 집이 가까우니 이동이 줄어 환경오염이 가장 적은 이상형으로 꼽힙니다.","환경을 활용·보전하며 자립적·안정적 순환구조를 갖는다":"생태도시는 환경을 활용하고 보전하면서 스스로 안정적으로 순환하는 구조를 갖습니다.","환경의 보전·관리에 관한 사항도 도시기본계획에 포함된다":"환경을 보전하고 관리하는 사항도 도시기본계획에 담습니다.","환지설계와 필지별 환지·청산 명세를 정하며 1/1000 환지예정지도는 포함되지 않는다":"환지계획에는 환지설계와 필지별 환지·청산 명세가 들어가며 1/1000 환지예정지도는 빠집니다.","활력 있는 가로 분위기 조성은 집중형이 아니라 노선형의 특징이다":"가로에 활기를 띠게 하는 것은 집중형이 아니라 노선형의 특징입니다.","회수 순위가 가장 낮아 위험도가 가장 크다":"자기자본 투자자는 돈을 돌려받는 순서가 가장 뒤라서 위험이 가장 큽니다.","획지분할방식이 아니라 밀도전이·밀도보너스제를 주로 쓴다":"PUD는 획지를 나누는 방식이 아니라 밀도전이나 밀도보너스제를 주로 씁니다.","획지 세장비는 1:1.2 정도이며 간선가로변에는 단독주택지를 배치하지 않는 것이 좋다":"획지의 세장비는 1:1.2쯤이 알맞고, 간선가로 쪽에는 단독주택지를 두지 않는 편이 좋습니다.","횡적 연결은 환상선, 도심-교외는 방사선으로 하며 도쿄·파리가 대표적이다":"방사환상형은 옆으로 잇는 길은 환상선, 도심과 교외를 잇는 길은 방사선으로 하며 도쿄와 파리가 대표적이에요.","흐름은 두 지점 간 거리의 제곱에 반비례한다":"흐름은 두 지점 사이 거리를 제곱한 값에 반비례해요.","흡인요인은 목적지의 매력, 배출요인은 출발지의 압박을 뜻한다":"흡인요인은 가려는 곳의 매력이고, 배출요인은 떠나는 곳에서 받는 압박입니다.","흡인요인이 아니라 농촌의 압출요인으로 인구만 팽창하는 현상이다":"가도시화는 도시가 끌어당겨서가 아니라 농촌에서 밀려나는 압출요인 때문에 인구만 부풀어 오르는 현상이에요.","히포다무스는 도시를 농부·무장 군인·예술가 3개 집단으로 구분했다":"히포다무스는 도시 주민을 농부, 무장 군인, 예술가의 3개 집단으로 나누었어요."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
